COLLDATA("seeratency","ur",[[283,"[تصویر: یمن اور اکسوم کی سلطنتیں (نقشہ)]\nموجودہ نجران شہر کے جنوب مغرب میں قدیم نجران کے کھنڈر ’’اخدود‘‘ کہلاتے ہیں۔\nنقشے کے اہم مقامات: عرب، بحیرہ احمر (بحیرہ قلزم)، خلیج عدن، بحیرۂ عرب، براعظم افریقہ، حبشہ (ایتھوپیا)، صومالیہ، بحر ہند، سودان، حضرموت، نجران، اخدود، سبا، معین، قتبان، حمیر، اکسوم\nاشارات: قتبان، سبا، حضرموت، اکسوم، اکسوم کے بیرونی مقبوضات، حمیر، معین","",{"v":100304,"im":["v1_p304.jpg"]}],[284,"[تصویر: مکاربین سبا کا پایہ تخت صرواح]\nمعنی ہے ’’بڑا‘‘ یا ’’بادشاہ‘‘ اور ’’مکارب‘‘ کے معنی ہیں ’’کاہن بادشاہ‘‘۔ مکاربین سبا کا پایہ تخت صرواح تھا جس کے کھنڈر آج بھی مارب اور صنعاء کے درمیان وادی واکفہ میں پائے جاتے ہیں اور محتریبہ کے نام سے مشہور ہیں۔ اسی دور میں مارب کے مشہور بند کی بنیاد رکھی گئی جسے عرب حجاز ’’سد‘‘ اور عرب یمن ’’عرم‘‘ کہتے تھے۔ عرم جنوبی عرب کی زبان کے لفظ عرمن سے ماخوذ ہے جس کے معنی بند کے ہیں۔ یمن کے قدیم کتبات میں یہ لفظ اس معنی میں بکثرت استعمال ہوا ہے، مثلاً: 542ء یا 543ء کا ایک کتبہ جو یمن کے حبشی گورنر ابرہہ نے سد مأرب کی مرمت کرانے کے بعد نصب کرایا تھا۔(1) اس میں وہ اس لفظ کو بار بار ’’بند‘‘ کے معنی میں استعمال کرتا ہے۔ سد مأرب تقریباً 800 ق م میں تعمیر کیا گیا۔ کہا جاتا ہے کہ اس دور میں سلطنت سبا کو اس قدر عروج حاصل ہوا کہ انھوں نے عرب کے اندر اور عرب کے باہر جگہ جگہ اپنی نو آبادیاں قائم کر لی تھیں۔\n§اہل سبا کا مذہب\nاہل سبا کا مذہب آفتاب پرستی تھا جیسا کہ ہدہد نے حضرت سلیمان علیہ السلام کو سبا کی ملکہ بلقیس کی خبر دیتے ہوئے کہا تھا: ﴿وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ اللَّهِ﴾ ’’میں نے اسے (ملکہ سبا) اور اس کی قوم کو دیکھا کہ وہ اللہ کے سوا سورج کو سجدہ کرتے ہیں۔‘‘(2) یہودیوں کی کتاب ترکوم میں بھی ملکہ بلقیس کے سورج کی عبادت کرنے کا ذکر ہے اور یونانی مورخ تھیوفراسٹینس آفتاب کے ہیکل میں بخورات کے ڈھیر کا ذکر کرتا ہے، نیز قبیلہ سبا کے بانی کا لقب ’’عبد شمس‘‘ مشہور ہے جس کے معنی ’’پرستار آفتاب‘‘ کے ہیں۔ اوائل اسلام میں یمن کی ایک عمارت کے کتبے پر یہ عبارت منقوش پائی گئی:","",{"v":100305,"fn":"(1) تفہیم القرآن: 192/4\n(2) النمل 27:24","im":["v1_p305.jpg"]}],[285,"بِسْمِ اللَّهِ هَٰذَا مَا بَنَاهُ شَمَّرْ يَرْعَشْ لِسَيِّدَةِ الشَّمْسِ\n’’اللہ کے نام سے، یہ وہ عمارت ہے جسے بادشاہ شمر یرعش نے سورج دیوی کے لیے بنایا۔‘‘(1) ملکہ بلقیس نے سیدنا سلیمان علیہ السلام کے پاس حاضر ہو کر اسلام قبول کر لیا تھا۔(2) بعد میں قوم سبا دوبارہ گمراہی کا شکار ہوگئی۔\nتاریخی آثار سے معلوم ہوتا ہے کہ قدیم زمانے سے قوم سبا میں ایک ایسا عنصر موجود تھا جو خدائے واحد کو مانتا تھا۔ تقریباً 650 ق م کے بعض کتبات بتاتے ہیں کہ سبا کے متعدد مقامات پر اس معبود کا نام ملکن دُسموی (آسمانوں کا مالک بادشاہ) لکھا گیا ہے، نیز 378ء کے ایک کتبے میں اللہ ذوسموی کے نام سے ایک عبادت گاہ کی تعمیر کا ذکر ملتا ہے۔ پھر 465ء کے ایک کتبے میں یہ الفاظ مرقوم ہیں: بنصر و ردا الهن بعل سمين وارضين (اس الہ کی مدد اور تائید سے جو آسمانوں اور زمین کا مالک ہے)۔ ایک اور کتبے (458ء) میں اسی الہ کے لیے رحمن کا لفظ بھی استعمال کیا گیا ہے۔ اصل الفاظ ہیں: بردا رحمنن (رحمن کی مدد سے)۔(3)\n§سد مأرب اور اس کی تباہی\nاہل سبا نے جو سد مأرب (ڈیم) تیار کیا تھا، وہ مارب شہر کے مشرق میں وادی اُذینہ میں واقع تھا۔(4) قوم سبا اور اس کے تعمیر کردہ بند کا ذکر قرآن کریم میں بھی ہوا ہے:\n[تصویر: سد مأرب کے آثار]","",{"v":100306,"fn":"(1) تاریخ ارض القرآن (کامل): 214,215/1، ملوك الأرض، ص: 110\n(2) النمل 27:44\n(3) تفہیم القرآن: 194/4\n(4) اطلس القرآن (اردو)، ص: 173، المنجد في الأعلام، ص: 510","im":["v1_p306.jpg"]}],[286,"﴿لَقَدْ كَانَ لِسَبَإٍ فِي مَسْكَنِهِمْ آيَةٌ ۖ جَنَّتَانِ عَن يَمِينٍ وَشِمَالٍ ۖ كُلُوا مِن رِّزْقِ رَبِّكُمْ وَاشْكُرُوا لَهُ ۚ بَلْدَةٌ طَيِّبَةٌ وَرَبٌّ غَفُورٌ ۝ فَأَعْرَضُوا فَأَرْسَلْنَا عَلَيْهِمْ سَيْلَ الْعَرِمِ وَبَدَّلْنَاهُم بِجَنَّتَيْهِمْ جَنَّتَيْنِ ذَوَاتَيْ أُكُلٍ خَمْطٍ وَأَثْلٍ وَشَيْءٍ مِّن سِدْرٍ قَلِيلٍ ۝ ذَٰلِكَ جَزَيْنَاهُم بِمَا كَفَرُوا ۖ وَهَلْ نُجَازِي إِلَّا الْكَفُورَ ۝ وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ الْقُرَى الَّتِي بَارَكْنَا فِيهَا قُرًى ظَاهِرَةً وَقَدَّرْنَا فِيهَا السَّيْرَ ۖ سِيرُوا فِيهَا لَيَالِيَ وَأَيَّامًا آمِنِينَ ۝ فَقَالُوا رَبَّنَا بَاعِدْ بَيْنَ أَسْفَارِنَا وَظَلَمُوا أَنفُسَهُمْ فَجَعَلْنَاهُمْ أَحَادِيثَ وَمَزَّقْنَاهُمْ كُلَّ مُمَزَّقٍ ۗ إِنَّ فِي ذَٰلِكَ لَآيَاتٍ لِّكُلِّ صَبَّارٍ شَكُورٍ ۝﴾\n’’سبا (قوم) کے لیے ان کی بستی میں یقیناً ایک عظیم نشانی تھی، دائیں اور بائیں طرف دو باغ تھے، (ہم نے کہا:) تم اپنے رب کے رزق سے کھاؤ اور اس کا شکر ادا کرو، (یہ) پاکیزہ شہر ہے اور رب بڑا بخشنے والا ہے۔ پھر انھوں نے (جب ہدایت سے) منہ موڑا تو ہم نے ان پر بند (ڈیم) کا سیلاب بھیج دیا اور ان کے دونوں باغوں کے بدلے میں ہم نے انھیں دو ایسے باغ دیے جو بد مزہ پھل، (بکثرت) جھاؤ اور کچھ بیریوں والے تھے۔ یہ ہم نے انھیں ان کی ناشکری کی سزا دی اور ہم ناشکروں ہی کو سزا دیتے ہیں۔ اور ہم نے ان (اہل سبا) کے اور ان بستیوں کے درمیان جن میں ہم نے برکت رکھی تھی، کئی بستیاں باہم متصل (سر راہ آباد) رکھی تھیں اور ان میں ہم نے چلنے (آنے جانے) کی منزلیں مقرر کر دی تھیں، (ہم نے کہا:) تم ان میں راتوں اور دنوں کو امن سے سفر کرو۔ پھر انھوں نے کہا: اے ہمارے رب! ہمارے سفروں میں دوری پیدا کر دے اور انھوں نے اپنے آپ پر ظلم کیا، چنانچہ ہم نے انھیں افسانے بنا ڈالا اور انھیں مکمل طور پر ٹکڑے ٹکڑے کر دیا، بلاشبہ اس میں ہر صابر و شاکر کے لیے عظیم نشانیاں ہیں۔‘‘(1)\n[تصویر: مارب کے کھنڈر]","",{"v":100307,"fn":"(1) سبا 34:15-19","im":["v1_p307.jpg"]}],[287,"[تصویر: سد مأرب اور سیل عرم (خاکہ)]\nخاکے کے اہم اجزا: دائیں طرف کے ڈیم کے سنگی آثار، دایاں باغ، ڈیم کی بلندی: 800 ذراع (492.8 میٹر)، سد مأرب کا منہدم شدہ حصہ، سد مأرب کا وہ حصہ جو اب تک باقی ہے، سیلاب کے بہاؤ کا راستہ، سیلاب کا رخ، جبل بلق (دائیں جانب)، جبل بلق (بائیں جانب)، بائیں باغ کو سیراب کرنے والی نہر، بائیں طرف آبادی کے آثار، بایاں باغ، اُذینہ ندی","",{"v":100308,"im":["v1_p308.jpg"]}],[288,"§سبا کا عروج و زوال\nابوالاعلیٰ مودودی لکھتے ہیں: قوم سبا کا عروج دراصل دو بنیادوں پر قائم تھا: ایک زراعت، دوسری تجارت۔ زراعت کو انھوں نے آب پاشی کے ایک بہترین نظام کے ذریعے سے ترقی دی تھی جس کے مثل کوئی دوسرا نظام آب پاشی بابل کے سوا قدیم زمانے میں کہیں نہ پایا جاتا تھا۔ ان کی سرزمین میں قدرتی دریا نہ تھے۔ بارش کے زمانے میں پہاڑوں سے برساتی نالے نکلتے تھے۔ انھی نالوں پر سارے ملک میں جگہ جگہ بند باندھ کر انھوں نے تالاب بنا لیے تھے اور ان سے نہریں نکال نکال کر پورے ملک کو اس طرح سیراب کر دیا تھا کہ قرآن مجید کی تعبیر کے مطابق ہر طرف باغ ہی باغ نظر آتے تھے۔ اس نظام آب پاشی کا سب سے بڑا مخزن آب وہ تالاب تھا جو شہر مأرب کے قریب کوہ بلق کی درمیانی ندی پر بند باندھ کر تیار کیا گیا تھا۔ مگر جب اللہ کی نظر عنایت ان سے پھر گئی تو پانچویں صدی عیسوی کے وسط میں یہ عظیم الشان بند ٹوٹ گیا اور اس سے نکلنے والا سیلاب راستے میں بند پر بند توڑتا چلا گیا یہاں تک کہ ملک کا پورا نظام آب پاشی تباہ ہو کر رہ گیا، پھر کوئی اسے بحال نہ کر سکا۔\nایک ہزار برس سے زیادہ مدت تک یہ قوم مشرق اور مغرب کے درمیان تجارت کا واسطہ بنی رہی۔ ایک طرف ان کی بندرگاہوں میں چین کا ریشم، انڈونیشیا اور مالا بار کے گرم مسالے، ہندوستان کے کپڑے اور تلواریں، مشرقی افریقہ کے زنگی غلام، بندر، شتر مرغ کے پر اور ہاتھی دانت پہنچتے تھے اور دوسری طرف یہ ان چیزوں کو مصر اور شام کی منڈیوں میں پہنچاتے تھے جہاں سے روم و یونان تک یہ مال روانہ کیا جاتا تھا۔ اس کے علاوہ خود ان کے علاقے میں لوبان، عود، عنبر، مشک، مر، قرفہ، قصب الذریرہ، سلیخہ اور دوسری ان خوشبودار چیزوں کی بڑی پیداوار تھی جنھیں مصر و شام اور روم و یونان کے لوگ ہاتھوں ہاتھ لیتے تھے۔\nاس عظیم الشان تجارت کے دو بڑے راستے تھے: ایک بحری، دوسرا بری۔ بحری تجارت کا اجارہ ہزار سال تک انھی سبائیوں کے ہاتھ میں تھا کیونکہ بحیرۂ احمر کی موسمی ہواؤں، زیر آب چٹانوں اور لنگر اندازی کے مقامات کا راز یہی لوگ جانتے تھے اور دوسری کوئی قوم اس خطرناک سمندر میں جہاز چلانے کی ہمت نہ رکھتی تھی۔ اس بحری راستے سے یہ لوگ اردن اور مصر کی بندرگاہوں تک اپنا مال پہنچایا کرتے تھے۔ بڑی راستے عدن اور حضرموت سے مأرب پر جا کر ملتے تھے اور پھر وہاں سے ایک شاہراہ مکہ، جدہ، یثرب، العلا، تبوک اور ایلہ سے گزرتی ہوئی پٹرا تک پہنچتی تھی۔ اس کے بعد ایک راستہ مصر کی طرف اور دوسرا راستہ شام کی طرف جاتا تھا۔ اس بری راستے پر جیسا کہ قرآن میں ارشاد ہوا ہے، یمن سے حدود شام تک سبائیوں کی نو آبادیاں مسلسل قائم تھیں اور شب و روز ان کے تجارتی قافلے یہاں","",{"v":100309}],[289,"سے گزرتے رہتے تھے۔ آج تک ان میں سے بہت سی نو آبادیوں کے آثار اس علاقے میں موجود ہیں اور وہاں سبائی و حمیری زبان کے کتبات مل رہے ہیں۔(1)\n[تصویر: عمرو بن معدیکرب سے منسوب کتبہ (مارب)]\nعلامہ سید سلیمان ندوی لکھتے ہیں: شہر مارب کے جنوب میں دائیں بائیں دو پہاڑ ہیں جن کا نام کوہ بلق ہے۔ دونوں پہاڑوں کے بیچ میں وادی اذینہ ہے۔ پہاڑوں سے پانی جمع ہو کر وادی اذینہ میں ایک دریا جاری ہو جاتا ہے۔ سبا نے ان دونوں پہاڑوں کے بیچ میں تقریباً 800 ق م میں سد مأرب تعمیر کیا تھا۔ سد مأرب کے بقیہ حصے پر جو کتبات ہیں، ان میں اس کے بانیوں (مکاربین سبا) کے نام شمع امر بین، سمہعلی ینوف، کرب ایل بین، ذمر علی اور یدع ایل پڑھے گئے ہیں۔ اس سے ثابت ہوتا ہے کہ یہ سد طویل زمانے میں مختلف سلاطین یمن کے عہد میں تعمیر ہوا ہے۔ اس نظام آب رسانی سے اس ریگستان کے اندر 200 مربع میل میں سینکڑوں کوس تک بہشت زار تیار ہو گئی تھی جس میں انواع و اقسام کے میوے اور خوشبودار درخت تھے۔ سد مأرب 542ء اور 570ء کے درمیان تباہ ہو گیا۔(2)\n۲ ملوک سبا (650 ق م تا 115 ق م): اس دور میں شاہان سبا نے ملک (بادشاہ) کا لقب اختیار کر لیا اور مارب کو دارالسلطنت بنایا۔ اس کا دوسرا نام شہر سبا تھا۔ مارب کا قصر شاہی سلحین تھا جس کے کھنڈر صنعاء سے 60 میل مشرق میں پائے جاتے ہیں۔(3) ماضی قریب میں مارب صوبہ بیضاء کا صدر مقام تھا۔ بیضاء یمن کے دارالحکومت صنعاء سے 130 میل کے فاصلے پر جنوب مشرق میں واقع ہے۔ آج کل مارب بجائے خود ایک صوبہ ہے۔\nسلطنت قتبان (قتبان)\nبنو قتبان کا جد امجد قتبان بن ردمان بن وائل بن غوث حمیری تھا۔(4) یمن کی یہ سلطنت 500 ق م سے لے کر 200ء تک سبا کے جنوب مشرق میں وادی بیجان میں قائم رہی۔ اس کا ذکر جنوبی عرب کے قدیم کتبوں اور یونانی اور رومی ادب میں ملتا ہے۔ اس\n[تصویر: سلطنت قتبان کا سکہ]","",{"v":100310,"fn":"(1) تفہیم القرآن: 197,198/4\n(2) تاریخ ارض القرآن (کامل): 202/1، المنجد في الأعلام، ص: 510، المفصل في تاريخ العرب قبل الإسلام: 285/2\n(3) تاریخ ارض القرآن (کامل): 188/1-196\n(4) المفصل في تاريخ العرب قبل الإسلام: 173/2","im":["v1_p310.jpg"]}],[290,"کا دارالحکومت تمنع تھا جو اس تجارتی شاہراہ پر واقع تھا جو حضرموت، سبا اور معین کی سلطنتوں میں سے گزرتی تھی۔ ان کا سب سے بڑا دیوتا عم تھا جس کی نسبت سے وہ لوگ بنو عم کہلاتے تھے۔ اس سلطنت کے حکمران مکرب کہلاتے تھے۔(1)\n§مملکت حمیر\nبنو حمیر آل سبا میں سے تھے اور یہ مغربی یمن میں بحیرۂ احمر اور بحیرۂ عرب کے متصل آباد تھے۔ ان پر ذو (امیر) حکومت کرتے تھے۔ قلعہ ریدان ان کا مسکن تھا۔ یہ قلعہ پایہ تخت ظفار کے متصل تھا۔ ظفار کے آثار صنعاء کے جنوب میں شہر یریم کے قریب ایک مدور پہاڑی پر پائے جاتے ہیں۔ سبا کی تباہی کے بعد حمیر نے مارب تک اپنی سلطنت کو وسعت دی۔ اس وقت ان کا لقب شاہی ’’ملک سبا و ذو ریدان‘‘ تھا۔ اسی دور میں سلطنت کے ایک حصے کی حیثیت سے پہلی مرتبہ لفظ ’’یمنت‘‘ اور ’’یمنات‘‘ کا استعمال شروع ہوا اور رفتہ رفتہ یمن اس پورے علاقے کا نام ہو گیا جو عمسیر سے عدن تک اور باب المندب سے حضرموت تک واقع ہے۔\n[تصویر: حمیری دور کے سکے]\nاہل حبش کے بعض کتبات میں ’’حمیر‘‘ اور ’’ارض حمیر‘‘ کے الفاظ ملتے ہیں، نیز یونانی مورخین نے حمیر کا پہلی بار ذکر 20 ق م میں کیا ہے۔ حمیر عربی اور حبشی زبان میں ’’حمر‘‘ (سرخ) سے مشتق ہوگا۔ چونکہ عرب اہل حبش کو اسود اور سودان کہتے ہیں، اس کے مقابلے میں اہل حبش عربوں کو حمیر، یعنی گورے رنگ کے کہتے ہوں گے۔ یمن کے حبشی فاتح ابرہہ کے ایک کتبے میں لکھا ہے: ’’بادشاہ حبشی حمیری فوج لے آیا۔ گویا کالی گوری دونوں پلٹنیں آئیں۔‘‘\n§حمیر کا طبقہ اولیٰ اور حبشیوں کا تسلط\nسبائے حمیر کی تاریخ دوسری صدی ق م کے اواخر (115 ق م) یا پہلی صدی ق م کے وسط سے شروع ہوتی ہے۔ پہلی صدی ق م سے تیسری صدی عیسوی کے اواخر تک حمیر کا طبقہ اول فرمانروائی کرتا رہا۔ ان سلاطین کا لقب ’’ملک سبا و ذو ریدان‘‘ تھا۔ دوسری صدی عیسوی شاہ اذینہ کے دور سے سبائی الاصل اکسومی حبشیوں نے یمن پر حملے شروع کیے، تاہم تبع اکبر حارث الرائش (شمر یرعش 280ء تا 315ء) نے انھیں حضرموت سے نکال باہر کیا اور یمن اور حضرموت دونوں کا پہلا بادشاہ بنا۔ پھر 340ء سے 375ء\n[تصویر: شاہ اذینہ کے دور کے سکے]","",{"v":100311,"fn":"(1) اردو دائرۃ معارف اسلامیہ: 266/1/16، ویکی پیڈیا انسائیکلوپیڈیا","im":["v1_p311.jpg"]}],[291,"تک اکسومی حبشی اکسوم سے یمن (حمیر) اور حضرموت پر قابض رہے۔ اس دوران شاہ اذینہ اور اس کے جانشین خود کو ’’ملک اکسوم و حمیر و ریدان و اثیوپیا و سبا و زیلع‘‘ کہتے تھے۔(1)\n§حمیر کا طبقہ ثانیہ یا متابعہ\nحمیر کے طبقہ ثانیہ کے سلاطین جن کا لقب ’’ملک سبا و ذو ریدان و حضرموت‘‘ ہے، عرب ان کو تبع (جمع تبابعہ) کہتے ہیں۔ ممکن ہے تبع عربی لفظ ’’متبوع‘‘ کے معنی میں ہو جس کی لوگ پیروی یا اطاعت کرتے ہیں لیکن یہ تحقیق جدید یہ حبشی لفظ ہے۔ حبشی زبان میں تبع کے معنی ’’قادر، جبار اور صاحب قوت‘‘ ہیں۔ پہلا تبع کلیکرب یا کتبات کے مطابق ملک یکرب تھا جس نے 375ء میں اکسومیوں کو نکال کر یمن و حضرموت پر اپنی حکومت قائم کی۔(2)\n§تبع اسعد ابوکرب کا قبول اسلام\nتبابعہ یمن میں سے تین زیادہ مشہور ہوئے: تبع اکبر حارث الرائش (280ء تا 315ء)، تبع اوسط اسعد ابوکرب بن کلیکرب (400ء تا 425ء) اور تبع اصغر حسان بن تبع (425ء تا 455ء)۔(3) تبع اسعد ابوکرب نے یہودیت قبول کر لی تھی۔\nسمہودی لکھتے ہیں: ‘‘جب تبع اول تبان اسعد ابوکرب بن کلیکرب مدینہ (یثرب) سے گزرا، اس کے ہمراہ چار سو علماء تھے۔ انھوں نے اسی شہر میں رہنے کا فیصلہ کیا۔ تبع اسعد نے وجہ پوچھی تو انھوں نے بتایا کہ ہم نے اپنی کتابوں میں لکھا پایا ہے کہ آخری اور عظیم ترین نبی جس کا نام احمد اور محمد (صلی اللہ علیہ وسلم) ہوگا، ہجرت کر کے اس شہر میں آئے گا، لہذا ہم یہیں قیام کریں گے، شاید ان سے ملاقات ہو جائے۔ تبع نے ان سب کے لیے گھر بار بنا دیے، پھر اس نے ایک مکتوب لکھا جس میں اپنے قبول اسلام کا ذکر کیا اور اس میں یہ شعر بھی رقم کیے:\nشَهِدْتُ عَلَىٰ أَحْمَدَ أَنَّهُ رَسُولٌ مِّنَ اللَّهِ بَارِيِّ النَّسَمِ\nفَلَوْ مُدَّ عُمْرِي إِلَىٰ عُمْرِهِ لَكُنْتُ وَزِيرًا لَّهُ وَابْنَ عَمٍّ\n’’میں احمد (صلی اللہ علیہ وسلم) کے بارے میں گواہی دیتا ہوں کہ وہ اللہ خالق کائنات کی طرف سے رسول ہیں۔ اگر میں نے ان کا زمانہ پایا تو میں ان کا معاون اور قرابت دار بنوں گا۔‘‘","",{"v":100312,"fn":"(1) ملخص از تاریخ ارض القرآن (کامل): 221/1-228\n(2) زیلع ان دنوں صومالیہ میں خلیج عدن کے ساحل پر واقع ہے۔ تاریخ ارض القرآن (کامل): 228,229/1\n(3) تاریخ ارض القرآن (کامل): 230,231/1"}],[292,"اس نے مکتوب پر سونے کی مہر لگائی اور سب سے بڑے عالم کے سپرد کرتے ہوئے کہا کہ اگر وہ نبی صلی اللہ علیہ وسلم کا زمانہ پائے تو انھیں دے دے اور اگر وہ ان کا عہد نہ پائے تو اس کے بیٹے یا پوتے یہ کام انجام دیں۔ اس نے نبی صلی اللہ علیہ وسلم کے لیے ایک مکان تعمیر کیا تا کہ آپ جب مدینہ تشریف لائیں تو اس میں قیام فرمائیں۔ وقت گزرنے پر اس مکان کے مالک ابو ایوب انصاری رضی اللہ عنہ بنے جو اسی عالم کی اولاد میں سے تھے۔(1)\nامام احمد، سہل بن سعد انصاری رضی اللہ عنہ کی روایت مرفوعاً بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\nلَا تَسُبُّوا تُبَّعًا فَإِنَّهُ قَدْ كَانَ أَسْلَمَ\n’’تبع کو بُرا بھلا مت کہو۔ بے شک اس نے اسلام قبول کر لیا تھا۔‘‘(2)\nتبابعہ کے عہد اول کے آخر میں رومیوں نے یمن کی سب سے بڑی بندرگاہ عدن پر فوجی تسلط قائم کر لیا اور ان کی مدد سے اکسومی حبشیوں نے حمیر و ہمدان کی باہمی کشاکش کا فائدہ اٹھاتے ہوئے 340ء میں پہلی بار یمن پر قبضہ کیا جو 375ء تک برقرار رہا۔\nاس کے بعد یمن کی آزادی تو بحال ہو گئی مگر ’’مارب‘‘ کے مشہور بند میں رخنے پڑنا شروع ہو گئے۔ جیسا کہ پہلے ذکر ہوا 542ء اور 570ء کے درمیان یہ بند ٹوٹ گیا۔(3) اور وہ عظیم سیلاب آیا جس کا ذکر قرآن مجید میں سیل عرم کے نام سے کیا گیا ہے۔(4) اس سیلاب میں بستیوں کی بستیاں ویران ہو گئیں اور بہت سے قبائل ادھر اُدھر بکھر گئے۔\n§حبشیوں کا یمن پر دوبارہ تسلط\nقیصر روم نے اپنے باجگزار شاہ حبش کو یمن پر حملے کی ترغیب دیتے ہوئے بحری بیڑہ مہیا کیا۔ یوں 525ء میں اریاط کے زیر قیادت ستر ہزار حبشی فوج نے حملہ کر کے یمن پر قبضہ کر لیا۔ کچھ عرصہ شاہ حبش کے گورنر کی حیثیت سے اریاط نے یمن پر حکمرانی کی۔ پھر اس کی فوج کے ایک ماتحت کمانڈر ابرہہ اشرم (ابرہہ نکھا) نے اسے قتل کر کے خود اقتدار پر قبضہ کر لیا۔ عام الفیل میں ابرہہ کی ہلاکت کے بعد اس کے دو بیٹے یکسوم اور مسروق یکے بعد دیگرے فرمانروائے یمن ہوئے۔\n[تصویر: ابرہہ کے سکے]","",{"v":100313,"fn":"(1) وفاء الوفا للسمهودي: 188,189/1\n(2) مسند أحمد: 340/5، السلسلة الصحيحة: 2423\n(3) المنجد في الأعلام، ص: 510، المفصل في تاريخ العرب قبل الإسلام: 285/2\n(4) سبا 34:16","im":["v1_p313.jpg"]}],[293,"§یمن پر ایرانی قبضہ\nچند سال بعد یمنیوں نے علم بغاوت بلند کر کے سیف ذی یزن حمیری کے بیٹے معدیکرب کی قیادت میں حبشیوں کو ملک سے نکال باہر کیا۔ یہ 575ء کا واقعہ ہے۔ شاہ معدیکرب نے کچھ حبشیوں کو اپنی خدمت اور شاہی جلوس کی زینت کے لیے روک لیا لیکن یہ شوق مہنگا ثابت ہوا۔ ان حبشیوں نے ایک روز معدیکرب کو دھوکے سے قتل کر دیا۔ اب سیف ذی یزن نے کسریٰ نوشیرواں کے دربار میں پہنچ کر فریاد کی کہ کووں نے ہمارا ملک تاراج کر دیا ہے۔ نوشیرواں نے پوچھا: کون سے کوے، حبشی یا ہندوستانی؟ سیف بولا: یہ کوے حبش سے آئے ہیں۔ نوشیرواں نے جواب دیا: ہمیں تمھارے دور دراز ملک پر قبضہ کرنے کی ہوس نہیں۔ اس میں بھیڑوں اور اونٹوں کے سوا رکھا ہی کیا ہے۔ پھر اس نے سفیر یمن کو دس ہزار درہم اور خلعت دے کر رخصت کر دیا۔ سیف نے دربار سے باہر نکلتے ہی درہموں کے دسوں کے دسوں توڑے شاہی محل کے غلاموں، کنیزوں اور دربانوں میں لٹا دیے۔ نوشیرواں کو پتہ چلا تو اس نے سیف کو واپس بلا کر شاہی عطیے کی اس بے توقیری کا سبب پوچھا۔\n[تصویر: خیام (یمن) کی ایک شاندار مسجد]\nاس نے جواب دیا: میں تمھارے ان سیم و زر کے سکوں کے تحفے کو کیا کرتا! جس ملک سے میں آیا ہوں، وہاں تو پہاڑ بھی سونے چاندی کے ہیں۔ نوشیرواں نے نرم پڑ کر اسے کچھ دن اور ٹھہرا لیا۔ مشاورت ہوئی تو وزرائے سلطنت نے رائے دی کہ شاہی بندی خانوں کے قیدی اس کے ہمراہ کر دیے جائیں کہ اگر یہ سارا گروہ مارا بھی گیا تو کچھ مجرم ہی کیفر کردار کو پہنچیں گے۔ نوشیرواں کو یہ رائے پسند آئی، چنانچہ آٹھ سو خونیں مجرم قید خانوں سے نکال کر سالخوردہ فوجی افسر وہرز کی کمان میں سیف کو دے دیے گئے۔ وہ انھیں چند جہازوں میں سوار کر کے حضرموت کے ساحل پر اترا۔ یمنیوں کی جمعیت بھی اس ایرانی فوج سے آملی۔ ابرہہ کا بیٹا مسروق مقابلے کو نکلا مگر وہرز کے ہاتھوں مارا گیا اور حبشی فوج بھاگ نکلی۔ یوں کسریٰ نے یمن کو فارس کا ایک صوبہ بنا لیا۔ وہرز یمن کا پہلا ایرانی گورنر مقرر ہوا۔ آخری عجمی گورنر باذان نے 628ء میں اسلام قبول کر لیا اور اس کے ساتھ ہی یمن فارسی اقتدار سے آزاد ہو کر اسلام کی عملداری میں آگیا۔(1)","",{"v":100314,"fn":"(1) محاضرات تاريخ الأمم الإسلامية: 29,30/1، تلیہ روم، مولانا ظفر علی خان، ص: 16-18","im":["v1_p314.jpg"]}],[294,"§اصحاب اُخدود\nنجران یمن کے حوالے سے کتب احادیث میں ایک حیرت انگیز واقعہ بیان ہوا ہے۔ امام مسلم اور امام احمد رحمہما اللہ نے سیدنا صہیب رضی اللہ عنہ سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n’’تم سے پہلے لوگوں میں ایک بادشاہ تھا۔ اس کا ایک جادوگر تھا۔ جادوگر بوڑھا ہوگیا تو اس نے بادشاہ سے کہا کہ میری عمر زیادہ ہوگئی ہے، موت قریب آگئی ہے، لہذا ایک بچہ میرے سپرد کر دو تا کہ میں اسے جادو سکھا دوں۔ بادشاہ نے ایک بچہ اس کے حوالے کر دیا اور اس نے بچے کو جادو سکھانا شروع کر دیا۔ جادوگر (کے ٹھکانے) اور بادشاہ کے محل کے درمیان ایک راہب بھی رہتا تھا۔ بچہ راستے میں راہب کے پاس رک جاتا اور اس کی گفتگو سنتا، اسے راہب کا طریقہ اور گفتگو بہت اچھی لگتی۔ جب وہ جادوگر کے پاس جاتا تو جادوگر اسے مارتا اور پوچھتا کہ دیر سے کیوں آئے ہو؟ اسی طرح جب وہ اپنے گھر جاتا تو گھر والے بھی پٹائی کرتے اور پوچھتے کہ دیر سے کیوں آئے ہو؟ اس نے اس امر کی شکایت راہب سے کی۔ راہب نے کہا کہ جب جادوگر تمھیں مارنے لگے تو اس سے کہہ دیا کرو کہ گھر والوں نے روک لیا تھا اور اسی طرح جب گھر والے مارنے لگیں تو کہہ دیا کرو کہ مجھے جادوگر کے پاس دیر ہوگئی۔ اس طرح دن گزرتے رہے۔\nخوفناک بلا کا صفایا: ایک دن اس نے دیکھا کہ ایک بہت بڑے خوفناک جانور نے لوگوں کا راستہ روک رکھا ہے اور لوگ اس کے خوف کی وجہ سے راستہ عبور نہیں کر سکتے۔ اس نے کہا: آج میں جان لوں گا کہ جادوگر افضل ہے یا راہب افضل ہے، چنانچہ اس نے ایک پتھر پکڑا اور کہا: اے اللہ! اگر راہب کا دین جادوگر کے دین کی نسبت تجھے زیادہ پسندیدہ ہے تو اس جانور کو ہلاک کر دے تا کہ لوگ راستے سے گزر جائیں۔ یہ کہہ کر اس نے پتھر مارا اور اس جانور کو ہلاک کر دیا۔ راستہ صاف ہو گیا اور لوگ گزرنے لگے۔ اس نے راہب کو یہ خبر دی تو اس نے کہا: اے میرے پیارے بیٹے! اب تم مجھ سے بھی (آگے) بڑھ گئے ہو اور یقیناً عنقریب تم آزمائش میں ڈالے جاؤ گے۔ اگر تمھیں آزمایا جائے تو میرے بارے میں کسی کو نہ بتانا۔\nدرباری ایمان لے آیا: اب یہ بچہ مادر زاد اندھوں اور پھلبہری (ایک بیماری جس سے بدن پر سفید داغ پڑ جاتے ہیں) اور دیگر بیماریوں میں مبتلا مریضوں کا علاج کرتا اور انھیں شفا نصیب ہو جاتی تھی۔ بادشاہ کا ایک ہم نشین تھا، وہ اندھا ہو گیا۔ اس نے اس بچے کی شہرت سنی، وہ اس کے پاس بہت سے تحائف لے کر آیا۔ اس نے کہا کہ مجھے شفا دے دو تو یہ تمام سامان تمھارا ہوگا۔ بچے نے کہا کہ میں کسی کو شفا نہیں دے سکتا، شفا دینا تو","",{"v":100315}],[295,"صرف اللہ تعالیٰ کا کام ہے۔ اگر تم اللہ پر ایمان لے آؤ تو میں دعا کرتا ہوں، اللہ تعالیٰ تمھیں شفا عطا فرما دے گا، چنانچہ وہ ایمان لے آیا۔ بچے نے اس کے لیے دعا کی تو اللہ تعالیٰ نے اسے شفا عطا فرمادی۔\nبادشاہ سے مکالمہ: یہ شخص اب بادشاہ کے پاس جا کر اسی طرح بیٹھنے لگا جس طرح پہلے بیٹھا کرتا تھا۔ بادشاہ نے اس سے پوچھا: اے فلاں! تمھاری نظر کس نے ٹھیک کی ہے؟ اس نے جواب دیا: میرے رب نے۔ بادشاہ نے پوچھا: میں نے ٹھیک کی ہے؟ اس نے کہا: نہیں، بلکہ اس نے جو میرا بھی رب ہے اور تیرا بھی رب ہے۔ بادشاہ نے پوچھا: کیا میرے علاوہ تیرا کوئی اور بھی رب ہے؟ اس نے جواب دیا: ہاں، میرا اور تیرا رب اللہ ہے۔ اس کے بعد بادشاہ اسے سزا دیتا رہا حتی کہ اس نے بچے کے بارے میں بتا دیا۔ بادشاہ نے بچے کو بلایا اور کہا: بیٹا! اب تمھارا جادو اس حد تک پہنچ گیا ہے کہ تم نے مادر زاد اندھے پن، پھلبہری اور دوسری بیماریوں کا علاج کر کے بیماروں کو شفا دینی شروع کر دی ہے۔ بچے نے جواب دیا: میں کسی کو شفا نہیں دیتا، شفا دینا تو صرف اللہ تعالیٰ کا کام ہے۔ بادشاہ نے کہا: میرا کام ہے! بچے نے جواب دیا: نہیں۔ بادشاہ نے پوچھا: کیا میرے سوا تیرا کوئی اور بھی رب ہے؟ بچے نے جواب دیا: ہاں، میرا اور تیرا رب تو اللہ ہے۔ اس پر بادشاہ اسے پکڑ کر سخت تکلیفیں دیتا رہا یہاں تک کہ بچے نے راہب کے بارے میں بتا دیا۔\nراہب پر ظلم و ستم: اب راہب کو لایا گیا۔ تب بادشاہ نے اس سے کہا کہ اپنے دین سے باز آ جاؤ تو اس نے انکار کر دیا۔ بادشاہ نے اس کے سر پر آرا رکھ کر اسے دو ٹکڑے کر دیا، پھر بادشاہ کے ہم نشین کو لایا گیا، اس سے بھی کہا گیا کہ اپنے اس دین کو چھوڑ دو۔ اس نے انکار کر دیا تو بادشاہ نے اس کے سر پر آرا رکھ کر اسے بھی چیر دیا حتی کہ اس کے جسم کے دو حصے ہو کر زمین پر گر گئے۔\nپہاڑ پر دُعا: اب اس نے اس بچے سے کہا کہ تم بھی اپنے دین کو ترک کر دو۔ اس نے بھی انکار کیا تو بادشاہ نے اسے ایک جماعت کے سپرد کر کے ایک پہاڑ کی طرف بھیج دیا اور کہا کہ جب تم اس پہاڑ کی چوٹی پر پہنچ جاؤ تو (اس بچے سے پوچھو کہ کیا تو اپنا دین چھوڑتا ہے) اگر یہ اپنا دین چھوڑ دے تو بہتر ورنہ اسے پہاڑ کی چوٹی سے نیچے گرا دو۔ وہ اسے لے گئے اور جب اسے لے کر پہاڑ کی چوٹی پر چڑھے تو بچے نے دعا کی: اللَّهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ ’’اے اللہ! تو ان کے مقابلے میں، جیسے تو چاہے، میرے لیے کافی ہو جا۔‘‘ اس سے پہاڑ لرزنے لگا اور وہ سب کے سب نیچے گر گئے (اور مر گئے)۔\nسمندر میں نصرت الہی: بچہ صحیح سلامت واپس آ گیا حتی کہ وہ بادشاہ کے دربار میں داخل ہوا۔ بادشاہ نے پوچھا: تیرے ساتھیوں نے کیا کیا؟ (کیا انھوں نے تجھے پہاڑ کی چوٹی سے نہیں گرایا؟) بچے نے جواب دیا","",{"v":100316}],[296,"کہ ان کے مقابلے میں اللہ تعالیٰ میرے لیے کافی ہو گیا۔ بادشاہ نے اسے ایک اور جماعت کے ساتھ ایک طویل و عریض کشتی پر سوار کرایا اور کہا کہ جب تم اسے لے کر سمندر کے درمیان پہنچ جاؤ تو (اس سے پوچھنا) اگر یہ اپنے دین سے باز آ جائے تو ٹھیک ورنہ اسے سمندر میں غرق کر دینا۔ جب وہ اسے لے کر سمندر میں داخل ہوئے تو بچے نے پھر وہی دعا کی: اے اللہ! تو ان کے مقابلے میں، جیسے تو چاہے، میرے لیے کافی ہو جا۔ چنانچہ وہ سب کے سب غرق ہو گئے مگر بچہ محفوظ رہا۔\nبسم اللہ کے تیر سے شہادت: بچہ صحیح سلامت واپس آ گیا اور بادشاہ کے دربار میں جا پہنچا۔ بادشاہ نے پوچھا: تیرے ساتھیوں نے کیا کیا؟ (کیا انھوں نے تجھے سمندر میں نہیں پھینکا؟) بچے نے جواب دیا کہ اللہ تعالیٰ ان کے مقابلے میں میرے لیے کافی ہو گیا، پھر اس نے بادشاہ سے کہا کہ تو مجھے اس وقت تک قتل نہیں کر سکتا جب تک تو وہ کام نہ کر لے جس کا میں تجھے حکم دوں۔ اگر تو نے وہ کام کیا، تب تو مجھے قتل کر سکتا ہے ورنہ تو مجھے قتل نہیں کر سکتا۔ بادشاہ نے پوچھا: وہ کیا ہے؟ بچے نے جواب دیا کہ سب لوگوں کو ایک کھلے میدان میں جمع کر، پھر مجھے ایک درخت کے تنے کے ساتھ لٹکا اور میرے ہی ترکش سے ایک تیر نکال اور پھر تیر کو کمان میں رکھ کر یہ پڑھ کر مجھے تیر مار: بِاسْمِ اللَّهِ رَبِّ الْغُلَامِ ’’بچے کے رب اللہ کے نام سے‘‘۔ اگر تو نے ایسا کیا تو یقیناً تو مجھے قتل کر سکتا ہے۔ بادشاہ نے ایسا ہی کیا، تیر کمان کے درمیان رکھا، پھر بچے کی طرف پھینکا اور کہا: بِاسْمِ اللَّهِ رَبِّ الْغُلَامِ تیر بچے کی کنپٹی پر لگا، اس نے اپنا ہاتھ اس جگہ رکھا جہاں اسے تیر لگا تھا، پھر وہ فوت ہو گیا۔\nمومن خندقوں کی آگ میں کود گئے: لوگوں نے یہ منظر دیکھا تو بے ساختہ پکار اٹھے کہ ہم اس بچے کے رب پر ایمان لے آئے۔ ہم اس بچے کے رب پر ایمان لائے۔ ہم اس بچے کے رب پر ایمان لائے۔ بادشاہ سے کہا گیا: دیکھ وہی ہوا جس سے تو ڈرتا تھا۔ اب تو سب لوگ اللہ پر ایمان لے آئے ہیں۔ اس پر بادشاہ نے حکم دیا اور تمام گلیوں کے دہانوں پر خندقیں کھودی گئیں اور ان میں آگ بھڑکا دی گئی، بادشاہ نے کہا کہ جو اس دین سے باز آ جائے، اسے چھوڑ دو ورنہ خندق کی آگ میں پھینک دو۔ لوگوں نے دوڑتے ہوئے ایک دوسرے سے آگے بڑھ کر ان خندقوں میں چھلانگیں لگانی شروع کر دیں۔ ایک عورت اپنے شیر خوار بچے کے ساتھ آئی۔ وہ آگ میں چھلانگ لگانے سے جھجکی تو بچہ فوراً بول اٹھا: اماں! صبر کر، تو یقیناً حق پر ہے۔(1)\nابن اسحاق رحمہ اللہ نے ’’سیرت‘‘ میں اس قصے کو ایک دوسرے انداز میں بیان کیا ہے۔ اس قصے کو بیان کرنے کے بعد ابن اسحاق نے لکھا ہے کہ بچے کے قتل کے بعد اہل نجران نے بچے کا دین، یعنی دین نصرانیت قبول کر لیا (جو اس","",{"v":100317,"fn":"(1) صحیح مسلم: 3005، مسند أحمد: 6/16-18"}],[297,"وقت تحریف اور شرک کی آمیزش سے پاک تھا، پھر ذونواس اپنے لشکر سمیت ان کے پاس آیا اور اس نے انھیں دعوت دی کہ یہودیت قبول کر لو یا پھر قتل ہونے کے لیے تیار ہو جاؤ تو ان لوگوں نے یہودیت قبول کرنے کے بجائے قتل ہونے کو ترجیح دی جس پر اس نے انھیں آگ میں جلایا اور تلوار سے ان کا قتل عام اور مثلہ کیا حتیٰ کہ بیس ہزار کے قریب انسان قتل ہوئے، چنانچہ ذونواس اور اس کے لشکر کے بارے ہی میں اللہ تعالیٰ نے یہ آیات نازل فرمائی ہیں:\n﴿قُتِلَ أَصْحٰبُ الْأُخْدُوْدِ ۝ النَّارِ ذَاتِ الْوَقُوْدِ ۝ إِذْ هُمْ عَلَيْهَا قُعُوْدٌ ۝ وَهُمْ عَلٰى مَا يَفْعَلُوْنَ بِالْمُؤْمِنِيْنَ شُهُوْدٌ ۝ وَمَا نَقَمُوْا مِنْهُمْ إِلَّا أَنْ يُّؤْمِنُوْا بِاللّٰهِ الْعَزِيْزِ الْحَمِيْدِ ۝ الَّذِيْ لَهٗ مُلْكُ السَّمٰوٰتِ وَالْأَرْضِ ؕ وَاللّٰهُ عَلٰى كُلِّ شَيْءٍ شَهِيْدٌ ۝﴾ (البروج 85:4-9)\n’’خندقوں والے ہلاک کیے گئے، ان خندقوں میں ایندھن والی آگ تھی، جبکہ وہ ان (کے کناروں) پر بیٹھے تھے اور وہ جو کچھ اہل ایمان کے ساتھ کر رہے تھے، اسے دیکھ رہے تھے۔ اور انھوں نے ان (مومنوں) سے اس کے سوا کسی چیز کا بدلہ نہیں لیا کہ وہ اللہ پر ایمان لائے تھے جو بڑا زبردست، نہایت قابل تعریف ہے، وہ ذات کہ اسی کے لیے آسمانوں اور زمین کی بادشاہی ہے اور اللہ ہی ہر چیز کو دیکھنے والا ہے۔‘‘(1)\nابن اسحاق، ابن ہشام رحمہما اللہ اور دیگر مورخین نے اس بادشاہ کا نام ذونواس قرار دیا ہے اور اصحاب الاخدود کی شہادت کا سبب یہودیت قبول کرنے سے انکار بتایا ہے۔ لیکن صحیح حدیث کی روشنی میں ان کی بات درست معلوم نہیں ہوتی کیونکہ ذونواس یہودی تھا اور اصحاب الاخدود کو شہید کرنے والا بادشاہ مشرک تھا جو اپنے رب ہونے کا دعویدار تھا۔ نجران کے لوگوں میں اب تک وہ جگہ معروف ہے جہاں اصحاب الاخدود کا واقعہ پیش آیا تھا۔\n[تصویر: مشہد اصحاب اخدود]","",{"v":100318,"fn":"(1) السيرة لابن إسحاق: 36,37/1، السيرة لابن هشام: 34-36/1","im":["v1_p318.jpg"]}],[298,"2\n§حیرہ (عراق) کی لخمی بادشاہت\n§عراق پر ایرانی، یونانی اور ساسانی تسلط\nعراق اور اس کے نواحی علاقوں پر ہخامنشی بادشاہ کوروش کبیر (سائرس یا ذوالقرنین) کے زمانے (557 ق م تا 529 ق م) ہی سے اہل فارس کی حکمرانی چلی آ رہی تھی یہاں تک کہ 330 ق م میں سکندر مقدونی نے دارا سوم کو شکست دے کر فارسیوں کی طاقت توڑ دی جس کے نتیجے میں ہخامنشی سلطنت ٹکڑے ٹکڑے ہو گئی۔\n323 ق م میں بابل میں سکندر اعظم کی وفات پر اس کی ایشیائی میراث سلوکیوں کے قبضے میں آئی۔ اس یونانی سلطنت کا بانی سکندر اعظم کا جرنیل سلوکس تھا۔ انھوں نے اپنا دارالحکومت سلوکیہ دجلہ کے مغربی کنارے آباد کیا۔ پھر 171 ق م سے 226ء تک شمالی ایران کے پارتھی وہاں حکمران رہے۔ اس دوران میں قحطانی قبائل نے ترک وطن کر کے عراق کے ایک بہت بڑے شاداب سرحدی علاقے میں بودوباش اختیار کی، پھر عدنانی تارکین وطن (مضر، ربیعہ اور بنو بکر) کا ریلا آیا اور انھوں نے لڑ بھڑ کر جزیرہ فراتیہ (الجزیرہ) کے ایک حصے کو اپنا مسکن بنا لیا۔\n[تصویر: سلوکی عہد کا سکہ]\n226ء میں اردشیر نے ایران میں ساسانی حکومت کی داغ بیل ڈالی اور اپنے ملک کی سرحد پر آباد عربوں کو زیر کیا تو قبیلہ قضاعہ نے ملک شام کی راہ لی، جبکہ حیرہ اور انبار کے عرب باشندوں نے باجگزار بننا گوارا کیا۔(1) انبار بغداد کے مغرب میں دریائے فرات کے کنارے 55 کلومیٹر کے فاصلے پر ایک شہر ہے۔ اس شہر میں بخت نصر نے بنی اسرائیل کے قیدی رکھے\n[تصویر: اردشیر ساسانی کے محل کے آثار]","",{"v":100319,"fn":"(1) محاضرات تاريخ الأمم الإسلامية: 30,31/1","im":["v1_p319.jpg"]}],[299,"[تصویر: اردشیر سوم کے سکے]\nتھے۔(1) ان دنوں عراق کا مغربی صوبہ انبار کہلاتا تھا۔ اردشیر سوم، نوشیرواں (خسرو اوّل)، ہرمز چہارم اور خسرو پرویز (خسرو ثانی) ساسانیوں کے مشہور حکمران تھے۔ (خسرو کو عربی میں ’’کسریٰ‘‘ کہتے ہیں۔) ان کا دارالحکومت مدائن سلوکیہ (سلوقیہ) کے بالمقابل دجلہ کے مشرقی کنارے آباد تھا۔ نبی صلی اللہ علیہ وسلم نوشیرواں عادل (م: 579ء) کے عہد میں پیدا ہوئے۔\n§حیرہ کی باجگزار بادشاہت\nاردشیر اول کے عہد میں حیرہ، بادیۃ العراق (صحرائے سادہ) اور الجزیرہ کے ربیعی اور مصری قبائل پر جذیمۃ الوضاح کی حکمرانی تھی۔ دراصل اردشیر نے محسوس کر لیا تھا کہ عرب باشندوں پر براہ راست حکومت کرنا اور انھیں سرحد پر لوٹ مار سے باز رکھنا ممکن نہیں، لہٰذا اس نے انھی میں سے جذیمہ کو حکمران بنا دیا تاکہ بوقت ضرورت رومیوں کے خلاف ان سے مدد لی جا سکے، چنانچہ شاہانِ حیرہ کے پاس فارسی فوج کی ایک یونٹ ہمیشہ رہا کرتی تھی جس سے بادیہ نشین عرب باغیوں کی سرکوبی کا کام بھی لیا جاتا تھا۔\n§حیرہ کے لخمی حکمران\n268ء میں جذیمہ فوت ہو گیا اور عمرو بن عدی بن نصر لخمی اس کا جانشین ہوا۔ یہ شاپور ساسانی کا ہم عصر تھا۔ اس کے بعد قباد بن فیروز کے عہد تک حیرہ پر لخمیوں کی مسلسل حکمرانی رہی۔ قباد کے عہد میں مزدک کا ظہور ہوا جو اباحیت کا علمبردار تھا۔ قباد اور اس کی بہت سی رعایا نے مزدک کی ہمنوائی کی۔ قباد نے حیرہ کے بادشاہ منذر بن ماء السماء کو پیغام بھیجا کہ تم بھی یہی مذہب اختیار کر لو۔ منذر بڑا غیرت مند تھا، انکار کر بیٹھا۔ نتیجہ یہ ہوا کہ قباد نے اس کو معزول کر کے اس کی جگہ مزدک کی دعوت کے ایک پیروکار حارث بن عمرو بن حجر کندی کو حیرہ کی حکمرانی سونپ دی۔\nقباد کے بعد فارس کی باگ ڈور کسریٰ نوشیرواں کے ہاتھ آئی۔ اسے مزدکیت سے سخت نفرت تھی۔ اس نے مزدک اور اس کے ہمنواؤں کی ایک بڑی تعداد کو قتل کروا دیا اور منذر کو دوبارہ حیرہ کا حکمران بنا دیا۔\n§جنگ ذی قار میں عربوں کی فتح\nمنذر بن ماء السماء کے بعد نعمان بن منذر (م: 15 قبل ہجرت/608ء) کے عہد تک حیرہ کی حکمرانی اس کی نسل","",{"v":100320,"fn":"(1) معجم البلدان، مادہ: أنبار، المنجد في الأعلام، ص: 72","im":["v1_p320.jpg"]}],[300,"میں رہی، پھر زید بن عدی بن زید عبادی نے کسریٰ (خسرو پرویز) سے نعمان بن منذر کی ایک جھوٹی شکایت کی جس پر کسریٰ بھڑک اٹھا اور نعمان کو اپنے پاس طلب کیا۔ نعمان چپکے سے بنو شیبان کے سردار ہانی بن مسعود کے پاس پہنچا اور اپنے اہل و عیال اور مال و دولت کو اس کی امانت میں دے کر کسریٰ کے پاس گیا۔ کسریٰ نے اسے قید کر دیا اور وہ قید ہی میں فوت ہو گیا۔ عدی ہی وہ شخص ہے جس نے کسریٰ کے دیوان شاہی میں عربی تحریروں کا آغاز کیا تھا۔\nادھر کسریٰ نے نعمان کو قید کرنے کے بعد اس کی جگہ ایاس بن قبیصہ طائی کو حیرہ کا حکمران بنایا اور اسے حکم دیا کہ ہانی بن مسعود سے نعمان کی امانت طلب کرے۔ ہانی غیرت مند تھا، اس نے صرف انکار ہی نہیں کیا بلکہ اعلان جنگ بھی کر دیا۔ پھر کیا تھا، ایاس اپنے جلو میں کسریٰ کے لاؤ لشکر اور مرزبانوں کی جماعت لے کر روانہ ہوا اور ذی قار کے میدان میں فریقین کے درمیان گھمسان کی جنگ ہوئی جس میں بنو شیبان کو فتح حاصل ہوئی اور فارسیوں نے شرمناک شکست کھائی۔ یہ پہلا موقع تھا جب عرب نے عجم پر فتح حاصل کی تھی۔ یہ واقعہ رسول اللہ صلی اللہ علیہ وسلم کی بعثت کے تھوڑا عرصہ بعد کا ہے۔ آپ صلی اللہ علیہ وسلم کی بعثت حیرہ پر ایاس کی حکمرانی کے آٹھ ماہ بعد ہوئی تھی۔\nایاس کے بعد کسریٰ نے حیرہ پر ایک فارسی حاکم مقرر کیا لیکن 632ء میں لخمیوں کا اقتدار پھر بحال ہو گیا اور منذر بن معرور نے باگ ڈور سنبھالی مگر ابھی اسے برسر اقتدار آئے صرف آٹھ ماہ ہوئے تھے کہ عہد صدیقی میں سیدنا خالد بن ولید رضی اللہ عنہ اور مجاہدین اسلام کی قیادت کرتے ہوئے حیرہ میں داخل ہو گئے اور لخمی سلطنت ہمیشہ کے لیے ختم ہو گئی۔(1) پھر دو تین سال کے اندر پورا عراق اسلامی خلافت کا حصہ بن گیا۔","",{"v":100321,"fn":"(1) تاريخ الطبري: 609/1، الكامل في التاريخ: 379/1، محاضرات تاريخ الأمم الإسلامية: 30-33/1، المنجد في الأعلام، ص: 257، اردو دائرہ معارف اسلامیہ: 55/10"}],[301,"3\n§شام کی غسانی بادشاہت\nجس زمانے میں عرب قبائل کی ہجرت زوروں پر تھی، قبیلہ قضاعہ کی چند شاخیں حدود شام میں آ کر آباد ہو گئیں۔ ان کا تعلق بنی سلیح بن حلوان سے تھا اور انھی کی ایک شاخ بنو ضجعم بن سلیح تھی جسے ضجاعمہ کے نام سے شہرت حاصل ہوئی۔ رومیوں نے عرب کے بدوؤں کی لوٹ مار روکنے اور فارسیوں کے خلاف استعمال کرنے کے لیے ان کے سر پر دیار شام کی حکمرانی کا تاج رکھ دیا۔\n§بصری الشام کے غسانی حکمران\nضجاعمہ کا دور حکومت پوری دوسری صدی عیسوی پر محیط رہا۔ اس کے بعد آل غسان نے بنو ضجعم کو شکست دی تو رومیوں نے انھیں دیارِ شام (موجودہ جنوب مشرقی شام اور اردن) کے عرب باشندوں کا بادشاہ تسلیم کر لیا۔ آل غسان کی حکومت میں تدمر، رقیم (بطراء)، عمان، معان وغیرہ شہر آباد تھے۔ اس کا پایہ تخت بصری (بصری الشام) تھا اور\n[تصویر: مکتوب نبی صلی اللہ علیہ وسلم بنام ابو شمر غسانی]\nرومیوں کے آلہ کار کی حیثیت سے دیار شام پر ان کی حکمرانی مسلسل قائم رہی۔ غسانی، جنھوں نے عموماً عیسائی مذہب اختیار کر لیا تھا، ایران و روم کے معرکوں میں روم کے ساتھ تھے۔ حارث بن جبلہ (متوفی 569ء) نہایت شجاع اور فراخ دل بادشاہ تھا۔ رومیوں نے اس کے جانشین منذر کے سر پر تاج رکھا۔ عہد نبوی میں حارث بن","",{"v":100322,"im":["v1_p322.jpg"]}],[302,"ابو شمر غسانی حکمران تھا۔ وہ غوطہ (دمشق) میں مقیم تھا جب نبی صلی اللہ علیہ وسلم کے سفیر شجاع بن وہب اسدی رضی اللہ عنہ نے اسے مکتوب نبوی پہنچایا۔\nانھی دنوں بلقاء کے حاکم شرحبیل بن عمرو غسانی نے نبی کریم صلی اللہ علیہ وسلم کے سفیر حارث بن عمیر ازدی رضی اللہ عنہ کو شہید کر دیا جس کے نتیجے میں غزوہ موتہ پیش آیا۔ پھر سیدنا عمر رضی اللہ عنہ کے زمانہ خلافت میں 15ھ/636ء میں یرموک کی جنگ پیش آئی اور آل غسان کا آخری حکمران جبلہ بن ایہم غسانی (م: 20ھ/641ء) حلقہ بگوش اسلام ہو گیا۔ اگرچہ اس کا غرور حکمرانی اسلامی مساوات کو زیادہ دیر تک برداشت نہ کر سکا اور وہ عہد فاروقی میں مرتد ہو کر شاہ روم کے پاس چلا گیا۔(1)\n[تصویر: وادی یرموک کا ایک منظر]\nاس کے ارتداد کی تفصیل کچھ اس طرح ہے: ایک حج کے موقع پر جبلہ سیدنا عمر رضی اللہ عنہ کے ہمراہ طواف کر رہا تھا۔ اس دوران میں ایک فزاری شخص کا پاؤں اس کی چادر پر آ گیا۔ اس پر جبلہ نے اسے تھپڑ مار کر اس کی ناک پھوڑ دی۔ فزاری نے عمر رضی اللہ عنہ سے شکایت کی۔ امیر المؤمنین نے جبلہ سے قصاص کا مطالبہ کیا تو وہ بولا: ’’یہ کیسے ہو سکتا ہے؟ میں بادشاہ ہوں اور یہ گھٹیا آدمی ہے۔‘‘ عمر رضی اللہ عنہ نے کہا: ’’اسلام مساوات کا سبق دیتا ہے۔‘‘ وہ کہنے لگا: ’’میرا تو خیال تھا کہ قبول اسلام کے بعد میرا مقام پہلے سے بلند ہو جائے گا۔‘‘ اس پر جبلہ نے عیسائیت قبول کرنے کی دھمکی دی۔ سیدنا عمر رضی اللہ عنہ نے کہا: ’’ارتداد کی صورت میں تمھیں قتل کر دیا جائے گا۔‘‘ جبلہ نے ایک رات کی مہلت مانگی جو مل گئی مگر وہ اسی رات اپنے لاؤ لشکر سمیت فرار ہو کر پہلے شام اور پھر قسطنطنیہ چلا گیا۔ قیصر نے اس کی بڑی آؤ بھگت کی۔ کچھ عرصہ بعد جبلہ نے اپنے اس فعل پر بہت ندامت ظاہر کی لیکن کفر کی حالت ہی میں وفات پا گیا۔(2)","",{"v":100323,"fn":"(1) محاضرات تاريخ الأمم الإسلامية: 35/1، تاريخ ارض القرآن (کامل): 62-64/2\n(2) البداية والنهاية: 65-69/8","im":["v1_p323.jpg"]}],[303,"4\n§عُمان کی بادشاہت\nنبی صلی اللہ علیہ وسلم سے دو تین پشت پہلے بنو مستکبر نے عُمان میں ایک وسیع حکومت قائم کر لی تھی جو ساسانی ایرانیوں کے ماتحت تھی۔ یہاں کا حکمران جلندی بن مستکبر عربی ادبیات میں خاصا مشہور ہے۔ عہد نبوی میں جلندی بن مستکبر کے بیٹے جیفر اور عبد مشترکہ طور پر عُمان کے حکمران تھے۔ جیفر بادشاہ تھا اور اس کا چھوٹا بھائی عبد امور سلطنت میں اس کا ہاتھ بٹاتا تھا۔ ان کا دارالحکومت صحار خلیج عُمان کے ساحل پر واقع تھا جو موجودہ دارالحکومت مسقط سے سوا دو سو کلومیٹر شمال مغرب میں ہے۔\n§شاہان عُمان آغوش اسلام میں\n[تصویر: مکتوب نبی صلی اللہ علیہ وسلم بنام جیفر و عبد (شاہان عُمان)]\nنبی کریم صلی اللہ علیہ وسلم کی دعوت پر جب عبد اور جیفر نے اسلام قبول کر لیا تو نبی کریم صلی اللہ علیہ وسلم نے سیدنا عمرو بن عاص رضی اللہ عنہ کو ان کے دربار میں اپنا وکیل مقرر فرمایا۔(1) جلد ہی اہل عُمان بھی حلقہ بگوش اسلام ہو گئے۔(2) لقیط بن مالک ازدی ذوالتاج نے سیدنا ابوبکر صدیق رضی اللہ عنہ کے دور خلافت میں نبوت کا دعویٰ کیا۔ اسے یا اس کے باپ کو یہ خطاب غالباً کسرائے ایران سے ملا ہو گا۔ یہاں دما کے مقام پر بستجان نامی ایرانی اسوار (فوجی گورنر) رہتا تھا۔ عُمان میں ازد کے علاوہ شمالہ اور حدان نامی قبائل بھی رہتے تھے۔ ان کے نام رسول اللہ صلی اللہ علیہ وسلم کا ایک مکتوب بھی ملتا ہے۔","",{"v":100324,"fn":"(1) الوثائق السياسية، عدد: 46\n(2) موسوعة العالم الإسلامي، ص: 130","im":["v1_p324.jpg"]}],[304,"عُمان میں صحار کا میلا یکم رجب کو شروع ہو کر پانچ دن رہتا تھا۔ یہاں بنو مستکبر بکری پر دس فیصد محصول وصول کرتے تھے۔ اس کے بعد دبا (عُمان) کا میلا لگتا تھا۔(1)\nبنو امیہ کے عہد میں عُمان کے لوگوں نے خارجی عقائد اختیار کر لیے اور وہ اتنے طاقتور ہو گئے کہ آلِ جلندی نے حجاج بن یوسف ثقفی کے لشکر کو شکست دی۔ بعد میں وہ اموی لشکر سے شکست کھا کر جزیرہ زنجبار (مشرقی افریقہ) کی طرف بھاگ گئے۔(2)","",{"v":100325,"fn":"(1) اردو دائرہ معارف اسلامیہ: 14/2/199\n(2) Histoire des Arabes, Cl. Huart: 2/257-282"}],[305,"5\n§سلطنت کندہ\nنجد میں کندہ کے نام سے ایک عرب حکومت 425ء سے 550ء تک قائم رہی جو مناذرہ، یعنی ملوک حیرہ کی ہمسری کا دعویٰ رکھتی تھی۔ بنو کہلان میں ثور (کندہ) بن عفیر کی اولاد میں سے حجر بن عمرو ملقب بہ آکل المرار حمیری بادشاہ حسان بن تبع کا سوتیلا بھائی تھا۔ حسان نے جب اندرونِ عرب لشکر کشی کی اور وہاں متعدد قبائل کو مطیع کر لیا تو حجر بن عمرو کو مفتوحہ قبائل کا حکمران مقرر کر دیا۔ کندہ ایک عظیم قحطانی قبیلہ ہے جو ثور (کندہ) بن عفیر بن عدی بن حارث بن مرہ بن ادد کی طرف منسوب ہے۔ اسے کندہ کا لقب اپنے والد کی نافرمانی کی وجہ سے ملا۔ اس کی یہ تین بڑی شاخیں معروف ہوئیں: معاویہ بن کندہ، السکون اور سکسک۔(1)\n§کندہ کے حکمران اور جنگ کلاب\n[تصویر: مملکت کندہ کے قدیم قلعے کے آثار]\nحجر بن عمرو سلطنت کندہ کا بانی ٹھہرا، پھر اس کا بیٹا عمرو بن حجر جانشین ہوا اور عمرو کے بعد حارث بن عمرو حکمران ہوا جو ساسانی بادشاہ قباد کے زمانے میں کچھ عرصہ حیرہ کا حاکم بھی رہا مگر نوشیرواں عادل کی تخت نشینی (531ء) کے بعد یہ حکومت اس کے ہاتھ سے نکل گئی۔ حارث نے 528ء میں سلطنت کندہ اپنے چار بیٹوں حجر، شرحبیل، معدی کرب اور سلمہ میں بانٹ دی تھی۔ بنو اسد پر حجر کی حکومت قائم ہوئی۔ شرحبیل بنو بکر، حنظلہ، عمرو بن تمیم اور رباب کے قبائل کا حاکم ہو گیا۔ سلمہ بنو تغلب اور نمر بن قاسط پر حکومت کرنے لگا اور سعد بن زید مناۃ، بنو قیس اور بنو کنانہ معدی کرب کے زیر فرمان آ گئے۔ کچھ عرصہ بعد ان میں جنگ کلاب برپا ہوئی جس میں شرحبیل مارا گیا۔ حجر نے اس جنگ میں کوئی حصہ نہیں لیا۔ 540ء میں بنو کلب قضاعی نے حارث بن عمرو کو قتل کر دیا۔ بنو اسد عدنانی پر اس کے بیٹے حجر کی حکومت رہی۔ پھر 550ء میں حجر بنو اسد کے ہاتھوں دھوکے سے مارا گیا تو اس کا بیٹا امرؤ القیس فرار ہو گیا اور قیصر سے امداد","",{"v":100326,"fn":"(1) معجم قبائل العرب: 998/3، المفصل في تاريخ العرب قبل الإسلام: 315/3","im":["v1_p326.jpg"]}],[306,"[تصویر: نقشہ: جزیرہ نمائے عرب کی سلطنتیں، قبائل اور مذاہب (قبل از اسلام)]\nاہم مقامات و عناصر: بحیرہ روم، ساسانی سلطنت (فارس)، عراق، دومة الجندل، سلطنت کندہ، نجد، غطفان، جزیرہ نمائے عرب، الربع الخالی، عُمان، خلیج عُمان، خلیج فارس، دارین، الاحقاف (عاد کا علاقہ)، حضرموت، ظفار، الفاو، بحیرہ عرب، مملکت اکسوم، حبشہ، سودان، براعظم افریقہ\nنوٹ: 1 عمان، بحرین اور حیرہ کی ریاستیں سلطنت فارس کے ماتحت تھیں۔ 2 غسانی عرب ریاست سلطنت روم کی باجگزار تھی۔ غسانی دارالحکومت بصری تھا۔ دمشق رومی صوبہ شام کا صدر مقام تھا۔ یمن ایران کا ایک صوبہ تھا۔ 3 کندہ قبل از اسلام کے عرب تمدن کا مرکز اور ایک آزاد ریاست تھی۔ کندہ کا دارالحکومت الفاو جو آج چھوٹی سی بستی ہے، جزیرہ نمائے عرب کے جنوب سے شمال اور شمال مشرق کو جانے والے قافلوں کی اہم تجارتی شاہراہ پر واقع تھا جو سبا، معین، قتبان، حضرموت اور حمیر سے آتے تھے۔ دارالحکومت ہونے کے باعث الفاو کی بڑی شہرت تھی۔ یہ سو سال سے زیادہ عرصے تک پھلی پھولی۔ دولت کندہ کے اس عہد عروج میں عظیم شاعر امرؤ القیس نے شہرت پائی۔\nعلامات (مختلف مذاہب کے پیروکار): عیسائی، یہودی، مجوسی، بت پرست","",{"v":100327,"im":["v1_p327.jpg"]}],[307,"لینے کے لیے قسطنطنیہ پہنچا مگر قیصر کے رویے سے اسے مایوسی ہوئی۔ آخر کار 560ء میں قیصر نے اسے انگورہ (انقرہ Ankara) میں مروا دیا۔(1) انقرہ شہر شمال مغربی اناطولیہ میں واقع ہے۔ 1341ھ/1923ء سے ترکی کا دارالحکومت ہے۔ اس شہر کو پہلے انگورہ (Angora) یا انگوریہ (Ankyra) کہتے تھے۔ ساتویں صدی عیسوی کے اوائل میں شاہ ایران خسرو پرویز نے اسے فتح کیا۔ 33ھ/654ء میں مسلم فاتحین یہاں پہنچے۔ 190ھ/806ء میں ہارون الرشید نے اسے دوبارہ فتح کیا۔ 464ھ/1071ء میں سلطان الپ ارسلان سلجوقی نے رومی حکمران دیوجانوس رومانوس کو شکست دے کر انقرہ سمیت پورے اناطولیہ کو اسلامی سلطنت میں شامل کر لیا۔ امیر تیمور نے 804ھ/1402ء میں جنگ انگورہ میں عثمانی سلطان بایزید اول یلدرم کو شکست دے کر قید کر لیا تھا۔(2)\n§الفاو: کندہ کا دارالحکومت\nکندہ کا دارالحکومت الفاو آج کل ’’قریہ‘‘ کہلاتا ہے۔ یہ ان قافلوں کی تجارتی شاہراہ پر واقع تھا جو سبا، معین، قتبان، حضرموت اور حمیر سے شمال مشرق کو جاتے تھے۔ یہ ریاست شمال میں دومتہ الجندل سے جنوب میں الربع الخالی تک پھیلی ہوئی تھی۔ 1972ء میں جامعہ الریاض کی ایک ٹیم نے الفاو میں کھدائی کا آغاز کیا اور یہاں بازار، محل، معبد اور مکانات کھود نکالے۔(3) الفاو نجران کے شمال مشرق میں 120 کلومیٹر کے فاصلے پر واقع ہے۔\n[تصویر: سلطنت کندہ کے دارالحکومت الفاو کے دریافت شدہ کھنڈر]","",{"v":100328,"fn":"(1) تاريخ ابن خلدون: 316-320/2، الكامل لابن الأثير: 315,316/1، العرب قبل الإسلام: 216-218/1، معجم قبائل العرب: 515,516/2\n(2) معجم البلدان، مادة: أنقرة، المنجد في الأعلام، ص: 78، الموسوعة العربية الميسرة: 248/1، اردو دائرۃ معارف اسلامیہ: 450/3، Oxford English Reference Dictionary\n(3) اٹلس سیرت نبوی، ص: 66، المفصل في تاريخ العرب قبل الإسلام: 178/1","im":["v1_p328.jpg"]}],[308,"6\n§تدمر کی عرب سلطنت\nصحرائے شام کے اندر واقع شہر تدمر (Palmyra) عروس الصحراء کہلاتا تھا۔ عربوں میں مشہور تھا کہ تدمر کی تعمیر میں جنوں نے سلیمان علیہ السلام کی مدد کی تھی۔ پہلی صدی عیسوی میں یہاں ایک طاقتور عرب مملکت قائم ہوئی جسے شاہ اذینہ ثانی اور ملکہ زنوبیا (زینب) کے عہد میں عروج حاصل ہوا۔ قیصر جالینوس (Gallienus) کے باجگزار کی حیثیت سے اذینہ (Odenathus) سلطنت روم کے تمام مشرقی مقبوضات کا فرمانروا بن گیا اور قیصر نے اسے آگسٹس کا خطاب دیا۔ 266-67ء میں اس کے قتل پر ملکہ زنوبیا نے مصر فتح کر کے سلطنت کو وسیع کیا۔\n[تصویر: ملکہ زنوبیا (زینب) کا سکہ]\n§سلطنت تدمر اور رومیوں کے ہاتھوں اس کی تباہی\nفتح مصر کے کچھ عرصہ بعد تدمر نے رومیوں کے خلاف بغاوت کر دی۔ 270ء میں زنوبیا نے شکست کھائی اور تدمر نے ہتھیار ڈال دیے لیکن 272ء میں جب اس نے دوبارہ بغاوت کی تو رومی حکمران اورلیان نے اس پر حملہ کیا اور ملکہ زنوبیا کو گرفتار کر کے روم بھیج دیا اور شہر تباہ کر دیا۔ اس کے آثار میں ’’بعل‘‘ دیوتا کا مندر مشہور ہے۔ رومی اقتدار کی ساڑھے تین صدیوں میں تدمر میں عیسائیت کو فروغ ملا۔ اس عرصے میں پورے شام میں عیسائیت پھیل گئی۔ عہد فاروقی میں شام اسلامی خلافت کا حصہ بن گیا۔(1)\n[تصویر: تدمر میں ’’بعل‘‘ دیوتا کا مندر]","",{"v":100329,"fn":"(1) انسائیکلوپیڈیا تاریخ عالم: 64,65/2، اٹلس فتوحات اسلامیہ، ص: 116 و 179 و 186، اردو دائرۃ معارف اسلامیہ: 572,573/5","im":["v1_p329.jpg"]}],[309,"7\n§حجاز کی امارت\nمکہ میں آبادی کا آغاز سیدنا اسماعیل علیہ السلام سے ہوا تھا۔(1) آپ نے 137 سال کی عمر پائی اور تاحیات مکہ کے سربراہ اور بیت اللہ کے متولی رہے۔ آپ کے بعد آپ کے دو صاحبزادگان نابت، پھر قیدار (یا قیدار پھر نابت) یکے بعد دیگرے مکہ کے والی ہوئے۔ ان کے بعد ان کے نانا مضاض بن عمرو جرہمی نے زمام کار اپنے ہاتھ میں لے لی اور اس طرح مکہ کی سربراہی بنو جرہم کی طرف منتقل ہو گئی۔(2)\n§بخت نصر کا عرب پر حملہ\n[تصویر: بخت نصر دوم کا سکہ]\nعراق میں بخت نصر کے ظہور سے کچھ پہلے بنو جرہم کی طاقت کمزور پڑ گئی اور مکہ کے افق پر عدنان کا سیاسی ستارہ جگمگانے لگا۔ اس کا ثبوت یہ ہے کہ بخت نصر نے ذات عرق میں عربوں سے جو معرکہ آرائی کی تھی، اس میں عرب فوج کا کمانڈر جرہمی نہ تھا۔(3)\nپھر بخت نصر دوم نے 586 ق م میں دوسرا حملہ کیا تو بنو عدنان یمن بھاگ گئے۔ اس وقت بنو اسرائیل کے نبی یرمیاہ علیہ السلام تھے۔ وہ عدنان کے بیٹے معد کو اپنے ساتھ ملک شام لے گئے اور جب بخت نصر کا زور ختم ہوا اور معد مکہ آئے تو انھوں نے قبیلہ جرہم کے ایک شخص جوشم (جرشم یا جوشن) بن جاہمہ کی لڑکی معانہ سے شادی کی اور اسی کے بطن سے نزار پیدا ہوئے۔(4)\n§مکہ پر بنو خزاعہ کا قبضہ\nمکہ میں بنو جرہم نے زائرین بیت اللہ پر زیادتیاں شروع کر دیں اور خانہ کعبہ کا مال کھانے سے بھی دریغ نہ کیا، چنانچہ جب بنو خزاعہ نے عمرو بن لحی کی قیادت میں مر الظہران میں پڑاؤ کیا تو انھوں نے حالات سے فائدہ اٹھاتے","",{"v":100330,"fn":"(1) كتاب مقدس (پیدائش 17:25)\n(2) قلب جزيرة العرب، ص: 230۔ ابن ہشام نے اسماعیل علیہ السلام کی اولاد میں سے صرف نابت کی تولیت کا ذکر کیا ہے۔\n(3) قلب جزيرة العرب، ص: 230\n(4) الكامل لابن الأثير: 206,207/1، الروض الأنف: 33/1","im":["v1_p330.jpg"]}],[310,"[تصویر: مر الظہران کا علاقہ]\nہوئے ایک مضری عدنانی قبیلے (بنو بکر بن عبد مناف بن کنانہ) کو ساتھ لے کر بنو جرہم کے خلاف جنگ چھیڑ دی اور انھیں مکہ سے نکال کر اقتدار پر خود قبضہ کر لیا۔ یہ واقعہ دوسری صدی عیسوی کے وسط کا ہے۔(1)\n§بنو جرہم نے چاہ زمزم پاٹ دیا\nبنو جرہم نے مکہ چھوڑتے وقت زمزم کا کنواں پاٹ دیا اور اس میں کئی تاریخی چیزیں دفن کر کے اس کے نشانات بھی مٹا دیے۔ محمد بن اسحاق کا بیان ہے کہ عمرو بن حارث بن مضاض جرہمی(2) نے خانہ کعبہ کے دو ہرن اور اس کے کونے میں لگا ہوا پتھر (حجر اسود) نکال کر زمزم کے کنویں میں دفن کر دیے اور اپنے قبیلے بنو جرہم کو ساتھ لے کر یمن چلا گیا۔ مسعودی نے لکھا ہے کہ اہل فارس پچھلے دور میں خانہ کعبہ کے لیے اموال و جواہرات بھیجتے رہتے تھے۔ ساسان بن بابک نے سونے کے بنے ہوئے دو ہرن، جواہرات، تلواریں اور بہت سا سونا بھیجا تھا۔ عمرو نے یہ سب زمزم کے کنویں میں ڈال دیا تھا۔(3) بنو جرہم کو مکہ سے جلاوطنی اور وہاں کی حکومت سے محروم ہونے کا بڑا قلق تھا، چنانچہ عمرو مذکور نے اسی سلسلے میں یہ اشعار کہے:\nكَأَنْ لَمْ يَكُنْ بَيْنَ الْحَجُونِ إِلَى الصَّفَا أَنِيسٌ ۝ وَلَمْ يَسْمُرْ بِمَكَّةَ سَامِرُ\nبَلَىٰ نَحْنُ كُنَّا أَهْلَهَا فَأَزَالَنَا صُرُوفُ اللَّيَالِي وَالْجُدُودُ الْعَوَاثِرُ\n’’لگتا ہے حجون سے صفا تک کوئی آشنا تھا ہی نہیں اور نہ کسی قصہ گو نے مکہ کی شبانہ محفلوں میں قصہ گوئی کی۔ کیوں نہیں! یقیناً ہم ہی اس کے باشندے تھے لیکن زمانے کی گردشوں اور ٹوٹی ہوئی قسمتوں نے","",{"v":100331,"fn":"(1) قلب جزيرة العرب، ص: 231,232\n(2) یہ وہ مضاض جرہمی نہیں جس کا ذکر سیدنا اسماعیل علیہ السلام کے واقعے میں گزر چکا ہے۔\n(3) مروج الذهب: 250/1","im":["v1_p331.jpg"]}],[311,"ہمیں اکھاڑ پھینکا۔(1)\nحضرت اسماعیل علیہ السلام کا زمانہ تقریباً 1800 قبل مسیح ہے۔ اس حساب سے مکہ میں قبیلہ جرہم کی حکمرانی لگ بھگ دو ہزار برس رہی۔\n§مضری قبائل کی امارت میں شرکت\nبنو خزاعہ نے مکہ پر قبضہ کرنے کے بعد بنو بکر کو شامل کیے بغیر تنہا اپنی حکمرانی قائم کی، البتہ تین اہم اور امتیازی مناصب ایسے تھے جو مضری قبائل کے حصے میں آئے:\n1 حاجیوں کو عرفات سے مزدلفہ لے جانا اور یوم النفر، یعنی 13 ذی الحجہ کو منیٰ سے روانگی کا پروانہ دینا۔ یہ اعزاز الیاس بن مضر کے خاندان بنو غوث بن مر کو حاصل تھا جو صوفہ کہلاتے تھے۔ 13 ذی الحجہ کو حاجی کنکریاں نہ مار سکتے تھے جب تک کہ پہلے صوفہ کا ایک مخصوص آدمی کنکریاں نہ مار لیتا۔ پھر حاجی کنکریاں مار کر فارغ ہو جاتے اور منیٰ سے روانگی کا ارادہ کرتے تو صوفہ کے لوگ منیٰ کی واحد گزرگاہ عقبہ کے دونوں جانب گھیرا ڈال کر کھڑے ہو جاتے اور جب تک خود گزر نہ لیتے، کسی کو گزرنے نہ دیتے۔ جب صوفہ ختم ہو گئے تو یہ اعزاز ایک عدنانی خاندان بنو سعد بن زید مناۃ تمیمی کی طرف منتقل ہو گیا۔\n2 10 ذی الحجہ کی صبح مزدلفہ سے منیٰ کی جانب افاضہ (روانگی)۔ یہ اعزاز بنو عدوان کو حاصل تھا۔\n3 حرام مہینوں کو آگے پیچھے کرنا۔ یہ کام جس کو وہ اعزاز سمجھتے تھے، بنو کنانہ کی ایک شاخ بنو فقیم بن عدی کے سپرد تھا۔(2)\n§عدنانی قبائل کا حجاز کے باہر پھیلاؤ\nمکہ پر بنو خزاعہ کا اقتدار کوئی تین سو برس قائم رہا(3) اور یہی زمانہ تھا جب عدنانی قبائل مکہ اور حجاز سے نکل کر نجد، اطراف عراق اور بحرین وغیرہ میں پھیلے اور مکہ کے اطراف میں صرف قریش کی چند شاخیں باقی رہیں جو خانہ بدوش تھیں۔ یہ بنو کنانہ کے چند متفرق گھرانے تھے مگر مکہ کی حکومت اور بیت اللہ کی تولیت میں ان کا کوئی حصہ نہ تھا یہاں تک کہ قصی بن کلاب کا ظہور ہوا۔(4)","",{"v":100332,"fn":"(1) السيرة لابن هشام: 114,115/1\n(2) السيرة لابن هشام: 44/1 و 119-122\n(3) معجم البلدان، مادة: مكة\n(4) محاضرات تاريخ الأمم الإسلامية: 36/1"}],[312,"§قصی بن کلاب کی مکہ واپسی\nقصی ابھی گود ہی میں تھے کہ ان کے والد کا انتقال ہو گیا۔ اس کے بعد ان کی والدہ نے بنو عذرہ کے ایک شخص ربیعہ بن حرام سے شادی کر لی۔ یہ قبیلہ چونکہ ملک شام کے اطراف میں رہتا تھا، اس لیے قصی کی والدہ وہیں چلی گئیں اور وہ قصی کو بھی اپنے ساتھ لے گئیں۔ جب قصی جوان ہوئے تو مکہ واپس آئے۔ اس وقت مکہ کا والی حلیل بن حبشیہ خزاعی تھا۔ قصی نے اس کی بیٹی حُبّیٰ سے نکاح کے لیے پیغام بھیجا۔ حلیل نے منظور کر لیا اور شادی کر دی۔(1)\n§تولیت کعبہ قصی کی تحویل میں\nجب حلیل کا انتقال ہو گیا تو قصی نے قریش اور کنانہ کے لوگوں کو ہمراہ لیا\n[تصویر: کعبہ کا پرانا تالا اور چابی]\nاور صوفہ کے اختیارات کو چیلنج کرتے ہوئے کہا: تم سے زیادہ ہم اس اعزاز کے حقدار ہیں۔ اس پر صوفہ نے لڑائی چھیڑ دی مگر قصی نے انھیں مغلوب کر کے ان کا اعزاز چھین لیا۔ یہی موقع تھا جب بنو خزاعہ اور بنو بکر نے قصی سے دامن کشی اختیار کر لی۔ اس پر قصی نے انھیں بھی للکارا۔ پھر کیا تھا، سخت جنگ چھڑ گئی اور طرفین کے بہت سے آدمی مارے گئے۔ اس کے بعد صلح کی آوازیں بلند ہوئیں اور بنو بکر کے ایک شخص یعمر بن عوف کو حکم بنایا گیا۔ یعمر نے فیصلہ کیا کہ خزاعہ کے بجائے قصی خانہ کعبہ کی تولیت اور مکہ کے اقتدار کا زیادہ حقدار ہے، نیز قصی نے جتنا خون بہایا ہے، سب رائیگاں قرار دے کر میں پاؤں تلے روندتا ہوں، البتہ خزاعہ اور بنو بکر نے جن لوگوں کو قتل کیا ہے، ان کی دیت ادا کریں اور خانہ کعبہ کو بلا حیل و حجت قصی کے حوالے کر دیں۔ اسی فیصلے کی وجہ سے یعمر کا لقب شداخ پڑ گیا۔(2) شداخ کے معنی ہیں: خون کو رائیگاں قرار دینے والا۔ اس فیصلے کے نتیجے میں قصی اور قریش کو مکہ کی سیادت حاصل ہو گئی۔ مکہ پر قصی کے تسلط کا یہ واقعہ 440ء کا ہے۔(3)\nقصی نے مکہ کا بندوبست اس طرح کیا کہ قریش کو اطراف مکہ سے بلا کر پورا شہر ان پر تقسیم کر دیا اور ہر خاندان کی بود و باش کا ٹھکانا مقرر کر دیا، البتہ مہینے آگے پیچھے کرنے والوں کو، نیز آل صفوان تھی، بنو عدوان اور بنو مرہ بن","",{"v":100333,"fn":"(1) السيرة لابن هشام: 117,118/1\n(2) السيرة لابن هشام: 123,124/1\n(3) قلب جزيرة العرب، ص: 232","im":["v1_p333.jpg"]}],[313,"عوف کو ان کے مناصب پر برقرار رکھا کیونکہ وہ سمجھتے تھے کہ یہ بھی دین ہے جس میں رد و بدل کرنا درست نہیں۔(1)\n§دار الندوہ کی تعمیر\nقصی کا ایک کارنامہ یہ بھی ہے کہ انھوں نے حرم کعبہ کے شمال میں دار الندوہ تعمیر کیا۔ اس کا دروازہ مسجد کی طرف تھا۔ دار الندوہ درحقیقت قریش کی پارلیمنٹ تھی جہاں تمام بڑے بڑے اور اہم معاملات کے فیصلے ہوتے تھے۔ قریش پر دار الندوہ کے بڑے احسانات ہیں کیونکہ یہ ان کی وحدت کا ضامن تھا اور یہیں ان کے الجھے ہوئے مسائل بحسن و خوبی طے ہوتے تھے۔(2)\nقصی کو سربراہی کے حسب ذیل اختیارات حاصل تھے:\n1 دار الندوہ کی صدارت، جہاں بڑے بڑے معاملات کے متعلق مشورے ہوتے اور لوگ اپنی لڑکیوں کی شادیاں منعقد کرتے تھے۔\n2 لواء، یعنی جنگ کا پرچم قصی ہی کے ہاتھوں باندھا جاتا تھا۔\n3 حجابہ، یعنی خانہ کعبہ کی پاسبانی۔ اس کا مطلب یہ ہے کہ خانہ کعبہ کا دروازہ قصی ہی کھولتے تھے اور وہی خانہ کعبہ کی خدمت اور کلید برداری کا کام انجام دیتے۔\n4 سقایہ (پانی پلانا اور کھانا کھلانا)۔ حوض میں حاجیوں کے لیے پانی بھر دیا جاتا اور اس میں کھجور اور کشمش ڈال کر اسے شیریں بنا دیا جاتا۔\n5 رفادہ (حاجیوں کی میزبانی کا انتظام)۔ اس مقصد کے لیے قصی نے قریش پر ایک خاص رقم عائد کر رکھی تھی۔ اس رقم سے وہ حاجیوں کے لیے کھانا تیار کراتے تھے۔(3)\n§اولاد قصی میں مناصب کی تقسیم\nقصی کا پہلا بیٹا عبد الدار تھا، مگر اس کے بجائے دوسرا بیٹا عبد مناف باپ کی زندگی ہی میں شرف و سیادت کے مقام پر پہنچ گیا تھا، تاہم قصی نے اپنے سارے مناصب اور اعزازات کی وصیت عبد الدار کے لیے کر دی، یعنی دار الندوہ کی ریاست، خانہ کعبہ کی حجابت، لواء، سقایہ اور رفادہ سب کچھ اسے دے دیا۔ اس کی وفات کے بعد اس","",{"v":100334,"fn":"(1) السيرة لابن هشام: 125/1\n(2) محاضرات تاريخ الأمم الإسلامية: 36/1 ، السيرة لابن هشام: 124,125/1 و 130\n(3) محاضرات تاريخ الأمم الإسلامية: 36,37/1 ، السيرة لابن هشام: 124,125/1"}],[314,"کے بیٹوں نے کسی نزاع کے بغیر اس کی وصیت پر عمل کیا۔ لیکن جب عبد مناف کی وفات ہو گئی تو اس کے بیٹوں کا ان مناصب کے سلسلے میں اپنے چچیرے بھائیوں، یعنی عبد الدار کی اولاد سے جھگڑا ہوا۔ اس باہمی چشمک کے نتیجے میں قریش دو گروہوں میں بٹ گئے۔ قریب تھا کہ دونوں میں جنگ ہو جاتی لیکن پھر انھوں نے صلح کی آواز بلند کی اور ان مناصب کو باہم تقسیم کر لیا، چنانچہ سقایہ اور رفادہ کے مناصب بنو عبد مناف کو دیے گئے اور دار الندوہ کی سربراہی، لواء اور حجابت بنو عبد الدار کے ہاتھ میں رہی۔ پھر بنو عبد مناف نے اپنے حاصل شدہ مناصب کے لیے قرعہ ڈالا تو قرعہ ہاشم بن عبد مناف کے نام نکلا، لہذا ہاشم ہی نے زندگی بھر سقایہ و رفادہ کا انتظام کیا، البتہ جب ہاشم بن عبد مناف کا انتقال ہو گیا تو ان کے بھائی مطلب نے ان کی جانشینی کی، مگر مطلب کے بعد ان کے بھتیجے عبد المطلب بن ہاشم نے، جو رسول اللہ صلی اللہ علیہ وسلم کے دادا تھے، یہ منصب سنبھالا اور ان کے بعد ان کی اولاد ان کی جانشین ہوئی۔ جب اسلام کا دور آیا تو نبی اکرم صلی اللہ علیہ وسلم کے چچا سیدنا عباس بن عبد المطلب رضی اللہ عنہ اس منصب جلیل پر فائز تھے۔(1)\n§ظہور اسلام کے وقت مکہ میں انتظامی عہدے\nظہور اسلام کے وقت مکہ کی شہری حکومت میں کل چودہ عہدے تھے جو دس عہدے داروں میں منقسم تھے۔ دس عہدے دار قریش کے دس قبائل سے منتخب ہوئے تھے۔ ان عہدوں کی تقسیم اس طرح تھی:\n§الف: مذہبی خدمات\n1 سقایہ (حاجیوں کے کھانے پینے اور ان کی میزبانی کا انتظام): عباس بن عبد المطلب رضی اللہ عنہ (بنو ہاشم)\n2 رفادہ (حاجیوں کی مالی اعانت کا انتظام): حارث بن عامر (بنو نوفل)\n3 عمارہ (خانہ کعبہ کو آباد کرنے کا انتظام): عباس بن عبد المطلب رضی اللہ عنہ (بنو ہاشم)\n4 سدانہ (خانہ کعبہ کی دربانی و کلید برداری): عثمان بن طلحہ رضی اللہ عنہ (بنو عبد الدار)\n5 ایسر (فال گیری یا قسمت دریافت کرنے کے لیے بتوں کے پاس رکھے گئے تیروں کی تولیت): صفوان بن امیہ رضی اللہ عنہ (بنو جمح)\n6 اموال محجرہ (بتوں کے نذرانوں اور جائدادوں کا انتظام): حارث بن قیس رضی اللہ عنہ (بنو سہم)","",{"v":100335,"fn":"(1) السيرة لابن هشام: 129/1-132 و 135-137 و 142 و 178,179 ، محاضرات تاريخ الأمم الإسلامية: 37/1"}],[315,"§ب: عدالتی خدمات\n7 ندوہ (عدالت اور مشورہ گاہ کا انتظام): عثمان بن طلحہ رضی اللہ عنہ (بنو عبد الدار)\n8 مشورہ (شوریٰ): یزید بن زمعہ اسدی رضی اللہ عنہ (بنو اسد)\n9 اشناق (دیت، جرمانوں کا نظم): ابوبکر صدیق رضی اللہ عنہ (بنو تیم)\n10 حکومہ (مقدمات کا فیصلہ): حارث بن قیس رضی اللہ عنہ (بنو سہم)\n§ج: جنگی خدمات\n11 عقاب (لواء، یعنی قومی پرچم کی علمبرداری): ابوسفیان رضی اللہ عنہ (بنو امیہ)\n12 قبہ (فوجی کیمپ کا انتظام): خالد بن ولید رضی اللہ عنہ (بنو مخزوم)\n13 اعنہ (شہسواروں کی سپہ سالاری): خالد بن ولید رضی اللہ عنہ (بنو مخزوم)\n14 سفارت: عمر بن خطاب رضی اللہ عنہ (بنو عدی)\n۱ الرحيق المختوم، ص: 40,41 ، تاریخ ارض القرآن (کامل): 79,80/2 ، الطبقات لابن سعد: 66-73/1","",{"v":100336}],[316,"8\n§عرب سرداریاں\nجو عرب قبائل حیرہ کے ارد گرد آباد تھے، انھیں حکومت حیرہ کے تابع مانا جاتا تھا۔ جن قبائل نے بادیۃ الشام (صحرائے شام) میں سکونت اختیار کی تھی، انھیں غسانی حکمرانوں کے تابع قرار دیا گیا مگر یہ ماتحتی صرف نام کی تھی، عملاً نہ تھی۔ ان دو مقامات کو چھوڑ کر اندرون عرب آباد قبائل بہر طور آزاد تھے۔\n§سرداری نظام حکومت کی خصوصیات\nعرب قبائل میں سرداری نظام رائج تھا۔ سیاسی وجود و تحفظ کی بنیاد قبائلی وحدت پر مبنی عصبیت اور اپنی سرزمین کی حفاظت و دفاع کے مشترکہ مفادات تھے۔ قبائلی سرداروں کا درجہ اپنی قوم میں بادشاہوں جیسا تھا۔ قبیلہ صلح و جنگ میں بہر حال اپنے سردار کے فیصلے کے تابع ہوتا تھا اور کسی حال میں اس سے سرتابی نہیں کر سکتا تھا۔ بعض سرداروں کا یہ حال تھا کہ اگر وہ بگڑ جاتے تو ہزاروں تلواریں یہ پوچھے بغیر بے نیام ہو جاتیں کہ سردار کے غصے کا سبب کیا ہے۔ چونکہ ایک ہی کنبے کے چچیرے بھائیوں میں سرداری کے لیے کشاکش بھی ہوا کرتی تھی، اس لیے اس کا تقاضا تھا کہ سردار اپنے قبائلی عوام کے ساتھ رواداری برتے، خوب مال خرچ کرے، مہمان نوازی میں پیش پیش رہے، حلم و بُردباری سے کام لے، شجاعت کا عملی مظاہرہ کرے اور غیرت مندانہ امور میں ان کا دفاع کرے تاکہ لوگوں کی نظر میں عموماً اور شعراء کی نظر میں خصوصاً، خوبی و کمالات کا جامع بن جائے (کیونکہ شعراء اس دور میں قبیلے کی زبان ہوا کرتے تھے) اور اس طرح اپنے مد مقابل حضرات سے بلند و بالا درجہ حاصل کر لے۔\n§سرداروں کے امتیازی حقوق\nسرداروں کے کچھ مخصوص اور امتیازی حقوق بھی ہوا کرتے تھے جنھیں ایک شاعر نے یوں بیان کیا ہے:\nلَكَ الْمِرْبَاعُ مِنْهَا وَالصَّفَايَا وَحُكْمُكَ وَالنَّشِيطَةُ وَالْفُضُولُ\n’’(اے سردار!) تمھارے لیے مال غنیمت کا ایک چوتھائی حصہ ہے، منتخب مال اور وہ مال ہے جس کا تم فیصلہ","",{"v":100337}],[317,"کر دو، جو سر راہ ہاتھ آ جائے اور جو تقسیم سے بچ رہے۔‘‘\nمرباع: مال غنیمت کا چوتھائی حصہ مرباع کہلاتا تھا۔\nصفایا: یہ وہ مال تھا جسے تقسیم سے پہلے ہی سردار اپنے لیے منتخب کر لیتا تھا۔ (صفی کی جمع صفایا ہے۔)\nنشیطہ: اس مال کو نشیطہ کہتے تھے جو اصل قوم تک پہنچنے سے پہلے راستے ہی میں سردار کے ہاتھ لگ جائے۔\nفضول: یہ وہ مال تھا جو تقسیم کے بعد بچ رہے اور لڑنے والوں کی تعداد پر برابر تقسیم نہ ہو، مثلاً: تقسیم سے بچے ہوئے اونٹ گھوڑے وغیرہ۔\nیہ سب اقسام کے مال سردار قبیلہ کا حق ہوا کرتے تھے۔(1)","",{"v":100338,"fn":"(1) الروض الأنف: 78/4 ، الرحيق المختوم، ص: 42"}],[318,"سیرت انسائیکلوپیڈیا\n§باب 4\n§جزیرہ نمائے عرب کے مذاہب اور مشرکانہ رسوم\nدین ابراہیمی میں قریش کی جاری کردہ بدعتیں، عمرو بن لُحی کی طرف سے بت پرستی کا آغاز، یہودیت، عیسائیت، مجوسیت اور صابئیت کے پیروکاروں اور ان کے مراکز کی تفصیلات","",{"v":100339,"im":["v1_p339.jpg"]}],[319,"﴿رَبَّنَا وَابْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُو عَلَيْهِمْ آيَاتِكَ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ﴾\n’’اے ہمارے رب! ان لوگوں کے لیے انھی میں سے ایک رسول بھیج، جو ان کے سامنے تیری آیتیں تلاوت کرے اور انھیں کتاب اور حکمت کی تعلیم دے اور انھیں پاک کرے، بے شک تو ہی غالب، خوب حکمت والا ہے۔‘‘ (البقرة 2:129)","",{"v":100340}],[320,"§اس باب میں\nجزیرہ نمائے عرب میں عمرو بن لُحی کے ذریعے سے رائج ہونے والی بت پرستی، پوجے جانے والے بتوں اور عرب کے مختلف علاقوں میں ان کے استھانوں کا تذکرہ ہے، نیز بت پرستی کی اہم رسوم کا تعارف کرایا گیا ہے۔ اس کے علاوہ قریش نے دین ابراہیمی میں جو بدعات شامل کر دی تھیں ان پر روشنی ڈالی گئی ہے، پھر یہودیت، عیسائیت، مجوسیت اور صابئیت اور ان کے پیروکاروں کے بارے میں بتایا گیا ہے کہ یہ مذاہب جزیرہ نمائے عرب میں کب متعارف ہوئے اور عہد نبوی میں ان کے مراکز کہاں کہاں تھے۔","",{"v":100341,"im":["v1_p341.jpg"]}],[321,"1\n§عرب میں بت پرستی\nعام باشندگان عرب حضرت اسماعیل علیہ السلام کی دعوت و تبلیغ کے نتیجے میں دین ابراہیمی کے پیروکار بن گئے تھے، اس لیے وہ صرف ایک اللہ کی عبادت کرتے تھے اور توحید پر کاربند تھے لیکن وقت گزرنے کے ساتھ ساتھ انھوں نے خدائی درس و نصیحت کا ایک حصہ بھلا دیا، پھر بھی ان کے اندر توحید اور دین ابراہیمی کے بعض شعائر باقی رہے حتیٰ کہ بنو خزاعہ کا سردار عمرو بن لُحی منظر عام پر آیا۔\n§عربوں میں بت پرستی کا آغاز\nعمرو بن لُحی نے ملک شام کا سفر کیا تو دیکھا کہ وہاں بتوں کی پوجا کی جا رہی تھی۔ اس نے پوچھا: یہ کیا ہے؟ لوگوں نے بتایا: ہم ان (بتوں) کے ذریعے سے بارش حاصل کرتے ہیں اور اپنے دشمن کے خلاف مدد طلب کرتے ہیں۔ اس نے کہا: یہ بت مجھے بھی دے دیں۔ انھوں نے عمرو بن لُحی کو ایک بت تحفے میں دے دیا، چنانچہ واپسی پر وہ بھی اپنے ساتھ ’’ہبل‘‘ بت لے آیا۔ اسے خانہ کعبہ کے اندر نصب کر دیا اور اہل مکہ کو اس کی پوجا کی دعوت دی۔ اہل مکہ نے اس پر لبیک کہا۔ اس کے بعد بہت جلد دیگر باشندگان حجاز بھی اہل مکہ کے نقش قدم پر چل پڑے۔(1) اس طرح عرب میں بت پرستی کا آغاز ہوا۔\nہبل کے علاوہ عرب کے قدیم ترین بتوں میں سے ’’مناۃ‘‘ تھا۔ اس کے بعد طائف میں ’’لات‘‘ نامی بت وجود میں آیا، پھر وادی نخلہ میں ’’عزیٰ‘‘ کی تنصیب عمل میں آئی۔ یہ چاروں عرب کے سب سے بڑے بت تھے۔ اس کے بعد حجاز کے ہر خطے میں شرک کی کثرت اور بتوں کی بھر مار ہو گئی۔ کہا جاتا ہے کہ ایک جن عمرو بن لُحی کے تابع یا اس کا ساتھی تھا، اس نے بتایا کہ قوم نوح کے بت ...... ود، سواع، یغوث، یعوق اور نسر ...... جدہ میں مدفون ہیں۔ اس اطلاع پر عمرو بن لُحی جدہ گیا اور ان بتوں کو کھود نکالا، پھر انھیں تہامہ لایا اور جب حج کا زمانہ آیا تو انھیں مختلف قبائل کے حوالے کیا۔ یہ قبائل ان بتوں کو اپنے اپنے علاقوں میں لے گئے۔ اس طرح ہر قبیلے میں، پھر ہر گھر","",{"v":100342,"fn":"(1) أخبار مكة للأزرقي: 117/1 ، المفصل في تاريخ العرب قبل الإسلام: 77/6"}],[322,"میں ایک ایک بت ہو گیا۔ پھر مشرکین نے مسجد الحرام کو بھی بتوں سے بھر دیا، چنانچہ جب مکہ فتح کیا گیا تو بیت اللہ کے اندر اور ارد گرد تین سو ساٹھ بت تھے۔(1)\n§سرزمین عرب کے بت\nاساف و نائلہ: یہ انسانی شکل کے بت تھے۔ عمرو بن لُحی نے انھیں زمزم کے پاس رکھ دیا تھا۔ لوگ ان کا طواف کرتے اور ساتھ قربانی بھی کرتے تھے۔ یہ بھی کہا جاتا ہے کہ اساف نامی مرد اور نائلہ نامی عورت کعبہ میں زنا کے مرتکب ہوئے تھے۔ جب لوگوں نے آکر انھیں دیکھا تو وہ پتھر بن چکے تھے۔ لوگوں نے انھیں عبرت کے لیے صفا اور مروہ پر رکھ دیا تھا مگر عمرو بن لُحی نے حرم میں ان کی پوجا شروع کر دی۔(2)\nاقیصر: زمانہ جاہلیت میں عربوں کے ایک معبود کا نام تھا۔ قبائل قضاعہ، لخم، جذام، عاملہ اور غطفان اس کی پوجا کرتے تھے۔ شام کی سطح مرتفع (مشارف) میں اس کا استھان تھا۔ ہشام نے کہا ہے: قضاعہ، لخم، جذام اور اہل شام اس کا حج کرتے تھے اور اس کے پاس سر منڈاتے تھے۔(3)\nالمجلس: یہ حضرموت کے علاقے میں کندہ کا بت تھا۔ اس کے خادم و متولی بنی شکامہ بن شعیب کندی تھے۔ اس بت کے نام ایک چراگاہ تھی جس میں اس پر چڑھائے جانے والے جانور چرتے تھے۔ اس کی شکل ایک ضخیم انسان کی سی تھی۔\n[تصویر: بعل دیوتا کا مندر (تدمر)]","",{"v":100343,"fn":"(1) أخبار مكة للأزرقي: 120,121/1 ، إغاثة اللهفان: 269/2\n(2) المفصل في تاريخ العرب قبل الإسلام: 266-268/6\n(3) إغاثة اللهفان: 264/2 ، إغاثة اللهفان: 265/2 ، معجم البلدان، مادة: أقيصر","im":["v1_p343.jpg"]}],[323,"[تصویر: عربوں کے اصنام اور مورتیں (نقشہ)]\nنقشے کے اہم مقامات: جزیرہ نمائے عرب، مکہ مکرمہ، مدینہ منورہ، طائف، جدہ، یمن، حضرموت، عمان، الاحساء، دارین، دومۃ الجندل، تبوک، عراق، مصر، سودان، حبشہ، فارس (ایران)، بحیرہ احمر (بحیرہ قلزم)، بحیرہ عرب، بحر ہند، خلیج عربی (خلیج فارس)، خلیج عمان، خلیج عدن، دریائے نیل، الربع الخالی\nوہ بت جن کا ذکر قرآن کریم میں ہے: سواع، العزیٰ، اللات، مناۃ، ود، یعوق، یغوث، نسر\nوہ بت جن کا ذکر قرآن کریم میں نہیں: المجلس، اساف و نائلہ، ذو الکفین، ذو الخلصہ، ذو الشریٰ، ہبل","",{"v":100344,"im":["v1_p344.jpg"]}],[324,"اسے سفید پتھر سے تراش کر بنایا گیا تھا۔ دومۃ الجندل کا بادشاہ اکیدر بنو شکامہ ہی سے تھا جسے رسول اللہ صلی اللہ علیہ وسلم نے لکھ کر امان دی اور اس نے اسلام قبول کر لیا۔ یہ بھی کہا جاتا ہے کہ وہ مرتد ہو کر پھر عیسائی بن گیا تھا۔(1)\nذو الخلصہ: زمانہ جاہلیت میں مکہ اور یمن کے درمیان ’’تبالہ‘‘ کے مقام پر ذو الخلصہ نامی مکان میں یہ بت نصب تھا۔ قبائل دوس، خثعم اور بجیلہ اس کی پوجا کرتے تھے۔ اسے ’’کعبہ یمانیہ یا کعبہ شامیہ‘‘ کہا جاتا تھا۔ جریر بن عبد اللہ بجلی رضی اللہ عنہ(2) نے اسے فتح مکہ کے بعد توڑا۔(3) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قیامت اس وقت تک قائم نہیں ہوگی یہاں تک کہ دوس قبیلے کی عورتوں کی سرینیں ذو الخلصہ پر حرکت کریں گی (وہ اس کا طواف کریں گی)‘‘(4)\n[تصویر: تبالہ کے مقام پر کعبہ یمانیہ کے آثار]\nذو الشریٰ: یہ دوس اور ازد قبائل کا دیوتا تھا اور عسیر کے علاقے میں اس کی پوجا ہوتی تھی۔ شریٰ تہامہ میں ایک پہاڑی مقام تھا۔ نبطیوں میں ذو الشریٰ اور حریس دیوتاؤں کا جوڑا تھا۔ ادوم (اردن) کے ایک پہاڑی مقام کا نام بھی ’’شریٰ‘‘ تھا اور یہاں بھی خصوصاً پٹرا (بطرا) میں ذو الشریٰ کو پوجا جاتا تھا۔(5)\nذو الکفین: یہ قبیلہ دوس کے سردار عمرو بن حمہ کا دیوتا تھا۔ سیدنا طفیل بن عمرو دوسی رضی اللہ عنہ فتح مکہ کے بعد نبی اکرم صلی اللہ علیہ وسلم کی اجازت سے واپس گئے اور جا کر ذو الکفین کو جلا دیا۔(6)\nسواع: قرآن مجید کی سورۃ نوح میں ود، یغوث، یعوق اور نسر نامی بتوں کے ساتھ سواع کا ذکر کیا گیا ہے، یعنی قوم نوح","",{"v":100345,"fn":"(1) نهاية الأرب، ص: 280,281 ، الأعلام: 171/3\n(2) تاريخ دمشق الكبير: 148/9\n(3) صحيح البخاري: 2823 و 4357 ، صحیح ابن حبان (ابن بلبان): 150/15 ، السيرة لابن هشام: 86/1\n(4) صحيح البخاري: 7116 ، صحیح مسلم: 2906\n(5) اٹلس سیرت نبوی، ص: 60 ، اردو دائرۃ معارف اسلامیہ: 44,45/10\n(6) إغاثة اللهفان: 265/2 ، اٹلس سیرت نبوی، ص: 60","im":["v1_p345.jpg"]}],[325,"ان پانچوں بتوں کو پوجتی تھی۔ عہد اسلام سے پہلے یثرب کے مغرب میں ینبع کے قریب رباط کے مقام پر سواع کی پوجا ہوتی تھی، نیز دومۃ الجندل میں قبیلہ ہذیل کے لوگ بھی اسے پوجتے تھے۔ سواع کی شکل عورت کی تھی۔(1)\nالضَّيْزَنَان: یہ ’’ضیزن‘‘ سے تثنیہ کا صیغہ ہے۔ لغت عرب میں ضیزن مزاحمت کے معنی میں استعمال ہوتا ہے۔ یہ دو بت تھے جنھیں جذیمہ الابرش یا منذر الاکبر نے حیرہ (عراق) کے دروازے پر نصب کیا تھا تا کہ جو بھی حیرہ میں داخل ہو، انھیں سجدہ کرے اور اس سے مقصود یہ تھا کہ آنے والے کی اطاعت کا امتحان لیا جائے۔(2)\nعائم: علامہ یاقوت لکھتے ہیں: ’’کلبی نے کہا ہے کہ ازد سراۃ کے بت کا نام عائم تھا۔‘‘(3)\nالعزیٰ: یہ نام أَعَزّ کی تانیث اور تفضیل کا صیغہ ہے جبکہ أَعَزّ بمعنی عزیز اور عُزّیٰ بمعنی عزیزہ لیا گیا ہے۔ مکہ سے چند میل دور وادی نخلہ میں ببول کا ایک درخت تھا جس کے نیچے عزیٰ کا تھان (آستانہ) تھا۔ عزیٰ کا بت حرم کعبہ میں بھی رکھا ہوا تھا جسے فتح مکہ کے وقت توڑا گیا۔ وادی نخلہ میں بنو کنانہ عزیٰ کو پوجتے تھے اور اسے توڑنے کے لیے سیدنا خالد بن ولید رضی اللہ عنہ کو بھیجا گیا تھا۔(4)\nاللات: طائف میں بنو ثقیف اس کی عبادت کرتے تھے۔ ’’لات‘‘ کے معنی ہیں: پانی وغیرہ میں ستو گھولنے والا۔ یہ ایک شخص تھا جو حاجیوں کو ستو گھول کر پلایا کرتا تھا۔ اس کی وفات کے طویل عرصہ بعد عمرو بن لُحی کے ایما پر اس کا بت بنا کر اس کی پوجا کی جانے لگی۔ قریش سونے سے پہلے لات اور عزیٰ کی پوجا پاٹ کرتے اور انھی کی قسم کھایا کرتے تھے۔(5)\nلات ایک مربع چٹان کو تراش کر بنایا گیا تھا اور بنو معتب (یا بنو عتاب) ثقفی اس کے مجاور تھے۔ انھوں نے اس پر ایک عمارت بنا رکھی تھی۔ قریش اور دیگر عرب بھی اس کی تعظیم اور طواف کرتے تھے۔ فتح طائف کے بعد مغیرہ بن شعبہ ثقفی رضی اللہ عنہ نے اسے مسمار کر دیا۔ لات کے استھان (آستانے) کی جگہ اب جامع مسجد طائف کا مینار واقع ہے۔(6)\nمنات: یہ بت قدیم ترین تھا اور بحیرہ احمر کے ساحل پر قدید کے قریب مشلل میں نصب تھا۔(7) لات، منات اور عزیٰ عرب کے سب سے بڑے بت تھے۔ ان تینوں کے نام سورۃ نجم میں آئے ہیں۔ منات کی پوجا کا آغاز بھی عمرو بن لُحی نے کیا تھا۔ تمام عرب خصوصاً اوس اور خزرج اس کی انتہائی تعظیم کرتے تھے۔ بنو ازد اور غسان منات کا حج بھی کرتے تھے۔ اوس اور خزرج حج کے بعد منات کے پاس آکر احرام اتارتے تھے۔ فتح مکہ کے لیے جاتے","",{"v":100346,"fn":"(1) المفصل في تاريخ العرب قبل الإسلام: 257-259/6 ، اٹلس سیرت نبوی، ص: 59\n(2) تاريخ الطبري: 440/1 ، لسان العرب، مادة: ضزن\n(3) إغاثة اللهفان: 266/2 ، معجم البلدان، مادة: عائم\n(4) لسان العرب، مادة: عزز ، المفصل في تاريخ العرب قبل الإسلام: 235/6\n(5) مسند أحمد: 222/4 و 362/5 ، تفسير ابن كثير، النجم 53:19 ، جوامع السيرة لابن حزم، ص: 257\n(6) السيرة لابن هشام: 186/4 ، المفصل في تاريخ العرب قبل الإسلام: 227-229/6\n(7) صحیح البخاري: 1643 و 1790"}],[326,"ہوئے نبی اکرم صلی اللہ علیہ وسلم کے حکم پر سیدنا علی رضی اللہ عنہ نے اس بت کو منہدم کر دیا۔(1)\nنسر: حمیر (یمن) کے علاقے میں نجران کے پاس قبیلہ ذی الکلاع کے لوگ اس کی پوجا کرتے تھے۔ آج کل نجران سعودی عرب کا شہر ہے جو سرحد یمن کی طرف واقع ہے۔ نسر پرندے (گدھ) کی شکل کا بت تھا۔(2)\nہبل: قریش کے سب سے بڑے دیوتا کا نام ہے۔ ہبل دراصل بت بعل (بعل) تھا جسے عربوں نے معرب کر لیا۔(3) ’’بعل‘‘ اہل شام کا دیوتا تھا۔ اس سے منسوب ’’بعلبک‘‘ لبنان کا قدیم شہر ہے۔ ’’بعل‘‘ کے لغوی معنی قوت کے ہیں اور مجازاً آقا کے معنی لیے جاتے ہیں۔ اسی لیے قرآن میں ’’بعل‘‘ شوہر کے معنی میں استعمال ہوا ہے۔ یہ بت قریش کو انسانی مورت کی شکل میں ملا تھا جو سرخ عقیق سے تراشا گیا تھا۔ اس کا دایاں ہاتھ ٹوٹا ہوا تھا، قریش نے وہ سونے کا بنوا کر لگا دیا۔ ’’ہبل‘‘ خاص کعبہ میں نصب تھا۔ فال کے پانسے اس کے آگے ڈالے جاتے تھے۔ قریش جنگوں میں (اُعْلُ هُبَل) ’’ہبل کی جے‘‘ کا نعرہ لگاتے تھے۔ فتح مکہ کے موقع پر سیدنا علی رضی اللہ عنہ نے اسے توڑ دیا تھا۔(4)\n[تصویر: بعل دیوتا کا مندر (بعلبک، لبنان)]\nود: یہ بت دومۃ الجندل میں نصب تھا اور بنو کلب اس کی پوجا کرتے تھے۔ قریش بھی اس بت کو پوجتے تھے۔ غزوۂ تبوک کے موقع پر خالد بن ولید رضی اللہ عنہ نے اسے توڑا تھا۔(5)\nیعوق: یہ بھی ان پانچ بتوں میں شامل تھا جو جدہ میں دفن تھے۔ یعوق کے معنی ہیں: ’’مصیبت روکنے والا‘‘۔ اس کی شکل گھوڑے کی تھی۔ یعوق یمن میں ارحب کے مقام پر نصب تھا۔ بنو ہمدان و خولان اس کی پوجا کرتے تھے۔ ارحب صنعاء سے دو راتوں کے فاصلے پر مکہ کی جانب واقع تھا۔(6)\nیغوث: یہ بت اکمہ مذحج (یمن) میں نصب تھا اور بنو مذحج اور ہمدان اس کی پوجا کرتے تھے۔ قبیلۂ طے کی شاخ انعم، مراد اور بنو غطریف بھی اسے پوجتے تھے۔ یغوث کے معنی ہیں: ’’فریاد کو پہنچنے والا‘‘ اور اس کی شکل شیر کی تھی۔(7)","",{"v":100347,"fn":"(1) المفصل في تاريخ العرب قبل الإسلام: 246-249/6\n(2) المفصل في تاريخ العرب قبل الإسلام: 263/6\n(3) تاريخ ارض القرآن (کامل): 137/2\n(4) الرحيق المختوم، ص: 45 ، المفصل في تاريخ العرب قبل الإسلام: 250-253/6\n(5) الرحيق المختوم، ص: 46 ، المفصل في تاريخ العرب قبل الإسلام: 255-257/6\n(6) معجم البلدان، مادة: يعوق ، المفصل في تاريخ العرب قبل الإسلام: 262,263/6\n(7) معجم البلدان، مادة: يغوث ، المفصل في تاريخ العرب قبل الإسلام: 260-262/6","im":["v1_p347.jpg"]}],[327,"§عرب بت پرستی کے اہم مراسم\nاہل جاہلیت کے ہاں بت پرستی کے ایسے خاص طریقے اور مراسم رائج تھے جو زیادہ تر عمرو بن لُحَی کی اختراع تھے۔ وہ لوگ سمجھتے تھے کہ عمرو بن لُحَی کی اختراعات دین ابراہیمی میں تبدیلی نہیں بلکہ بدعت حسنہ ہیں۔ ان کے ہاں رائج بت پرستی کے چند اہم مراسم درج ذیل ہیں:\n۱ دور جاہلیت کے مشرکین بتوں کے پاس مجاور بن کر بیٹھتے تھے۔ وہ ان کی پناہ ڈھونڈتے، انھیں زور زور سے پکارتے، حاجت روائی و مشکل کشائی کے لیے ان سے التجائیں کرتے اور سمجھتے تھے کہ وہ اللہ سے سفارش کر کے ہماری مراد پوری کرا دیں گے۔\n۲ وہ بتوں کا حج و طواف کرتے تھے، ان کے سامنے عجز و نیاز سے پیش آتے تھے اور انھیں سجدہ کرتے تھے۔\n۳ وہ بتوں کے لیے نذرانے اور قربانیاں پیش کرتے تھے اور قربانی کے جانور کبھی بتوں کے آستانوں پر لے جا کر ذبح کرتے اور کبھی کسی بھی جگہ ذبح کر لیتے مگر بتوں کے نام پر ذبح کرتے تھے۔ ذبح کی ان دونوں صورتوں کا ذکر اللہ تعالیٰ نے قرآن مجید میں کیا ہے۔ ارشاد باری تعالیٰ ہے:\n﴿وَمَا ذُبِحَ عَلَى النُّصُبِ﴾\n’’اور (وہ جانور بھی حرام ہیں) جو آستانوں پر ذبح کیے گئے ہوں۔‘‘(1)\nدوسری جگہ ارشاد ہے:\n﴿وَلَا تَأْكُلُوا مِمَّا لَمْ يُذْكَرِ اسْمُ اللَّهِ عَلَيْهِ﴾\n’’اور اس جانور کا گوشت مت کھاؤ جس پر اللہ کا نام نہ لیا گیا ہو۔‘‘(2)\n۴ بتوں سے تقرب کا ایک طریقہ یہ بھی تھا کہ مشرکین اپنی صوابدید کے مطابق اپنے کھانے پینے کی چیزوں اور اپنی کھیتی اور چوپاؤں کی پیداوار کا ایک حصہ بتوں کے لیے خاص کر دیتے تھے۔ اس کے ساتھ ایک حصہ اللہ تعالیٰ کے لیے بھی خاص کر دیتے، پھر مختلف اسباب کی بنا پر اللہ تعالیٰ کا حصہ تو بتوں کی طرف منتقل کر دیتے تھے لیکن بتوں کا حصہ کسی بھی حال میں اللہ تعالیٰ کی طرف منتقل نہیں کرتے تھے۔ اللہ تعالیٰ کا ارشاد ہے:\n﴿وَجَعَلُوا لِلَّهِ مِمَّا ذَرَأَ مِنَ الْحَرْثِ وَالْأَنْعَامِ نَصِيبًا فَقَالُوا هَٰذَا لِلَّهِ بِزَعْمِهِمْ وَهَٰذَا لِشُرَكَائِنَا فَمَا كَانَ لِشُرَكَائِهِمْ فَلَا يَصِلُ إِلَى اللَّهِ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَائِهِمْ سَاءَ مَا يَحْكُمُونَ﴾","",{"v":100348,"fn":"(1) المائدة 5:3\n(2) الأنعام 6:121"}],[328,"’’اور انھوں نے اس میں سے اللہ کے لیے ایک حصہ ٹھہرایا جو اس نے کھیتی اور چوپایوں کی شکل میں پیدا کیا، پھر اپنے خیال کے مطابق کہنے لگے: یہ اللہ کے لیے ہے اور یہ ہمارے شرکاء (دیوتاؤں) کے لیے ہے، چنانچہ جو ان کے شرکاء کے لیے ہوتا ہے، وہ تو اللہ تک نہیں پہنچتا (مگر) جو اللہ کے لیے ہوتا ہے، وہ ان کے شرکاء تک پہنچ جاتا ہے۔ کتنا برا ہے جو وہ فیصلہ کرتے ہیں۔‘‘(1)\n۵ بتوں کے تقرب کا ایک طریقہ یہ بھی تھا کہ مشرکین کھیتی اور چوپائے کے اندر مختلف قسم کی نذریں مانتے تھے۔ اللہ تعالیٰ کا ارشاد ہے:\n﴿وَقَالُوا هَٰذِهِ أَنْعَامٌ وَحَرْثٌ حِجْرٌ لَّا يَطْعَمُهَا إِلَّا مَن نَّشَاءُ بِزَعْمِهِمْ وَأَنْعَامٌ حُرِّمَتْ ظُهُورُهَا وَأَنْعَامٌ لَّا يَذْكُرُونَ اسْمَ اللَّهِ عَلَيْهَا افْتِرَاءً عَلَيْهِ﴾\n’’اور ان مشرکین نے اپنے (جھوٹے) خیال کے مطابق کہا: یہ چوپائے اور کھیتی ممنوع ہیں۔ انھیں بس وہی کھا سکتا ہے جسے ہم چاہیں اور بعض چوپائے ہیں جن کی پشت (پر سواری) حرام کر دی گئی ہے اور کچھ چوپائے ایسے ہیں جن پر وہ لوگ (بوقت ذبح) اللہ کا نام نہیں لیتے، یہ سب وہ اللہ پر جھوٹ گھڑتے ہوئے کرتے ہیں۔‘‘(2)\n۶ انھی جانوروں میں بحیرہ، سائبہ، وصیلہ اور حام تھے۔\nبحیرہ اور سائبہ: ابن اسحاق کہتے ہیں کہ بحیرہ، سائبہ کی بچی کو کہا جاتا ہے۔ سائبہ اس اونٹنی کو کہا جاتا ہے جس سے دس بار پے در پے مادہ بچے پیدا ہوں، درمیان میں کوئی نر پیدا نہ ہو۔ ایسی اونٹنی کو آزاد چھوڑ دیا جاتا تھا۔ اس پر سواری نہیں کی جاتی تھی۔ اس کے بال نہیں کاٹے جاتے تھے اور مہمان کے سوا کوئی اس کا دودھ نہیں پیتا تھا۔ اس کے بعد یہ اونٹنی جو مادہ بچہ جنتی، اس کا کان چیر دیا جاتا اور اسے بھی اس کی ماں کے ساتھ آزاد چھوڑ دیا جاتا۔ اس پر سواری نہ کی جاتی، اس کے بال نہ کاٹے جاتے اور مہمان کے سوا کوئی اس کا دودھ نہ پیتا۔ یہی بحیرہ ہے اور اس کی ماں سائبہ ہے۔\nوصیلہ: اس بکری کو کہا جاتا تھا جو پانچ دفعہ پے در پے دو دو مادہ بچے جنتی (پانچ بار میں دس مادہ بچے پیدا ہوتے)، درمیان میں کوئی نر پیدا نہ ہوتا۔ اس بکری کو اس لیے وصیلہ کہا جاتا تھا کہ وہ سارے مادہ بچوں کو ایک دوسرے سے جوڑ دیتی تھی۔ اس کے بعد اس بکری سے جو بچے پیدا ہوتے، ان کا گوشت صرف مرد کھا سکتے تھے، عورتیں نہیں کھا سکتی تھیں، البتہ اگر کوئی بچہ مردہ پیدا ہوتا تو اسے مرد عورت سبھی کھا سکتے تھے۔\nحام: اس نر اونٹ کو کہتے تھے جس کی جفتی سے پے در پے دس مادہ بچے پیدا ہوتے، درمیان میں کوئی نر پیدا نہ ہوتا۔","",{"v":100349,"fn":"(1) الأنعام 6:136\n(2) الأنعام 6:138"}],[329,"ایسے اونٹ کی پیٹھ محفوظ کر دی جاتی تھی۔ اس پر سواری کی جاتی تھی نہ اس کے بال کاٹے جاتے تھے بلکہ اسے اونٹوں کے ریوڑ میں جفتی کے لیے آزاد چھوڑ دیا جاتا تھا۔ اس کے سوا اس سے کوئی دوسرا فائدہ نہ اٹھایا جاتا تھا۔ دور جاہلیت کی بت پرستی کے ان طریقوں کی تردید کرتے ہوئے اللہ تعالیٰ نے فرمایا:\n﴿مَا جَعَلَ اللَّهُ مِن بَحِيرَةٍ وَلَا سَائِبَةٍ وَلَا وَصِيلَةٍ وَلَا حَامٍ وَلَٰكِنَّ الَّذِينَ كَفَرُوا يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ وَأَكْثَرُهُمْ لَا يَعْقِلُونَ﴾ (المائدة 5:103)\n’’اللہ نے نہ کوئی بحیرہ، نہ کوئی سائبہ، نہ کوئی وصیلہ اور نہ کوئی حام بنایا ہے لیکن جن لوگوں نے کفر کیا، وہ اللہ پر جھوٹ گھڑتے ہیں اور ان میں سے اکثر عقل نہیں رکھتے۔‘‘\nایک دوسری جگہ فرمایا:\n﴿وَقَالُوا مَا فِي بُطُونِ هَٰذِهِ الْأَنْعَامِ خَالِصَةٌ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰ أَزْوَاجِنَا وَإِن يَكُن مَّيْتَةً فَهُمْ فِيهِ شُرَكَاءُ﴾ (الأنعام 6:139)\n’’اور ان مشرکین نے کہا کہ ان چوپایوں کے پیٹ میں جو کچھ ہے، وہ خالص ہمارے مردوں کے لیے ہے اور ہماری عورتوں پر حرام ہے، البتہ اگر وہ مردہ ہو تو اس میں (مرد اور عورتیں) سب شریک ہیں۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے: ’’عمرو بن لُحَی پہلا شخص تھا جس نے بتوں کے نام پر جانور چھوڑے۔‘‘(1) سید التابعین سعید بن مسیب رحمہ اللہ کا بیان ہے کہ ان جانوروں کا دودھ ان کے بتوں کے لیے وقف تھا۔(2)\nعرب اپنے بتوں کے ساتھ یہ سب کچھ اس غلط عقیدے کے ساتھ کرتے تھے کہ یہ بت انھیں اللہ تعالیٰ کے قریب کر دیں گے اور اللہ تعالیٰ کے حضور ان کی سفارش کریں گے، چنانچہ قرآن مجید میں بتایا گیا ہے کہ مشرکین کہتے تھے:\n﴿مَا نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونَا إِلَى اللَّهِ زُلْفَىٰ﴾(3)\n’’ہم ان (بتوں) کی عبادت محض اس لیے کرتے ہیں کہ وہ ہمیں اللہ کے زیادہ قریب کر دیں۔‘‘\n﴿هَٰؤُلَاءِ شُفَعَاؤُنَا عِندَ اللَّهِ﴾(4)\n’’یہ (بت) اللہ کے پاس ہمارے سفارشی ہیں۔‘‘","",{"v":100350,"fn":"(1) السيرة لابن هشام: 89/1، الرحيق المختوم، ص: 48,49\n(2) صحيح البخاري: 4623\n(3) الزمر 39:3\n(4) يونس 10:18"}],[330,"2\n§عرب میں یہودیت\nجزیرہ نمائے عرب میں یہود بھی آباد تھے۔ عرب کی طرف ان کی ہجرت دو بار عمل میں آئی تھی۔ 722 ق م میں شاہ اشور سارگون دوم نے شمالی فلسطین کی یہودی ریاست ’’اسرائیل‘‘ کی اینٹ سے اینٹ بجا دی تو یہود کو ترک وطن کرنا پڑا۔ پھر شاہ بابل بخت نصر دوم کے ہاتھوں 586 ق م میں یروشلم کی تباہی، ہیکل سلیمانی کی بربادی اور ایک لاکھ یہودیوں کی عراق جلا وطنی کا نتیجہ یہ ہوا کہ یہود کی ایک جماعت فلسطین چھوڑ کر حجاز کے شمالی اطراف میں آ بسی۔\n§یثرب میں یہود کی آمد\nجب ٹائٹس (Titus) کی زیر قیادت 70ء میں رومیوں نے فلسطین پر قبضہ کیا اور یروشلم اور ہیکل سلیمانی دوسری مرتبہ برباد ہوئے تو متعدد یہودی قبیلے حجاز بھاگ آئے اور یثرب، خیبر اور تیماء میں اپنی باقاعدہ بستیاں بسا لیں اور قلعے اور گڑھیاں تعمیر کر لیں۔ انھی تارکین وطن یہود کے ذریعے سے عرب باشندوں میں بھی کسی قدر یہودی مذہب کا رواج ہوا۔\n§ظہور اسلام کے وقت یہودی قبائل\nظہور اسلام کے وقت مشہور یہودی قبائل یہ تھے: بنو نضیر، بنو مصطلق، بنو قریظہ اور بنو قینقاع۔(1) سمہودی نے بیان کیا ہے\n[تصویر: آثار بنو قریظہ (خیبر)]","",{"v":100351,"fn":"(1) قلب جزيرة العرب، ص: 251","im":["v1_p351.jpg"]}],[331,"’’کہ پہلے اور بعد میں آ کر بسنے والے یہودی قبائل کی تعداد بیس سے زیادہ تھی۔‘‘(1)\n§یہودیت یمن میں\nیہودیت کو یمن میں بھی فروغ حاصل ہوا۔ یہاں اس کے پھیلنے کا سبب تبان (تبع) اسعد ابو کرب تھا۔ ابن ہشام لکھتے ہیں کہ جب تبان اسعد مشرق کی مہم سے فارغ ہو کر واپس یثرب پہنچا تو اس نے بنو قریظہ کے دو یہودی علماء کی فہمائش پر یہودیت قبول کر لی اور پھر انھیں اپنے ساتھ یمن لے گیا اور ان کے ذریعے سے یہودیت کو یمن میں وسعت\n[تصویر: یمن میں یہودی بستی بیت باس عبد]\nاور پھیلاؤ حاصل ہوا۔ ابو کرب کے بعد اس کا بیٹا یوسف ذو نواس یمن کا حاکم ہوا تو اس نے یہودیت کے جوش میں نجران کے عیسائیوں پر ہلہ بول دیا اور انھیں مجبور کیا کہ یہودیت قبول کریں، مگر انھوں نے انکار کر دیا۔ اس پر ذو نواس نے خندق کھدوائی اور اس میں آگ جلا کر بوڑھے، بچے، مرد، عورتیں سب بلا تمیز آگ کے الاؤ میں جھونک دیے۔ کہا جاتا ہے کہ اس حادثے کا شکار ہونے والوں کی تعداد بیس سے چالیس ہزار کے درمیان تھی۔ یہ اکتوبر 523ء کا واقعہ ہے۔(2) قرآن مجید نے سورہ بروج میں اسی واقعے کا ذکر کیا ہے۔ اصحاب الاخدود کی شہادت کے ذمہ دار بادشاہ کے بارے میں بعض مؤرخین نے اختلاف کیا ہے۔ وہ کہتے ہیں کہ ذو نواس یہودی تھا جبکہ اصحاب الاخدود کی شہادت کا ذمہ دار مشرک بادشاہ تھا جو اپنے رب ہونے کا دعویدار تھا۔(3) دار السلام کے منیجنگ ڈائریکٹر مولانا عبد المالک مجاہد اپنے سفر نجران (ستمبر 2011ء) کے مشاہدات میں لکھتے ہیں: ‘‘جب ہم اصحاب الاخدود کے علاقے میں داخل ہوئے تو سامنے مٹیالے رنگ کے پہاڑ نظر آ رہے تھے۔ یہ علاقہ دس مربع کلومیٹر ضرور ہوگا۔ آدھا کلومیٹر سے کچھ زیادہ چلنے کے بعد وہ گھائیاں شروع ہو جاتی ہیں","",{"v":100352,"fn":"(1) وفاء الوفا للسمهودي: 165/1\n(2) السيرة لابن هشام: 20-36/1\n(3) دیکھیے: \"یمن کی سلطنتیں\" کے ذیل میں \"اصحاب اخدود\"","im":["v1_p352.jpg"]}],[332,"’’جہاں اصحاب الاخدود کا واقعہ پیش آیا تھا۔ بڑے بڑے پتھروں سے چھوٹے چھوٹے کمرے بنے ہوئے تھے جن میں بعض دیواریں چند فٹ بلند تھیں۔ یہ کٹی پھٹی جگہ تھی۔ بعض اونچی جگہیں ٹیلوں کے مشابہ تھیں۔ کم و بیش ایک کلومیٹر لمبی اور 300 میٹر چوڑی جگہ پر یہ خندقیں کھودی گئی تھیں اور پھر ان کی چھوٹی چھوٹی چار دیواریاں بنائی گئی تھیں کہ ان میں آگ دہکائی جا سکے۔ ان کھائیوں کے دائیں جانب ایک بڑا سا دائرہ نما گڑھا نظر آیا جس میں کئی سو افراد بیٹھ کر تماشا دیکھ سکتے تھے۔ غالباً اسی جگہ بادشاہ اور اعیان مملکت ان مظلوموں کو شہید ہوتے دیکھ رہے تھے۔‘‘(1)\n[تصویر: اخدود نامی بستی کے قدیم آثار (نجران)]","",{"v":100353,"fn":"(1) ماہنامہ \"ضیائے حدیث\" لاہور (ستمبر 2011ء)","im":["v1_p353.jpg"]}],[333,"3\n§عرب میں عیسائیت\nبلاد عرب میں عیسائی مذہب کی آمد حبشی اور رومی قبضہ گیروں اور فاتحین کے ذریعے سے ہوئی۔ یمن پر حبشیوں کا قبضہ پہلی بار 340ء میں ہوا اور 378ء تک برقرار رہا۔ اس دوران میں یمن میں مسیحی مشن کام کرتا رہا۔\n§نجران میں عیسائیت\nیمن پر حبشی تسلط کے زمانے میں ایک مستجاب الدعوات اور صاحب کرامات زاہد جس کا نام فیمیون تھا، نجران پہنچا اور وہاں کے باشندوں میں عیسائی مذہب کی تبلیغ کی۔ اہل نجران نے اس کی اور اس کے دین کی سچائی کی کچھ ایسی علامات دیکھیں کہ وہ عیسائیت کے حلقہ بگوش ہو گئے۔(1)\nنجران میں کعبہ مشرفہ (مکہ مکرمہ) کی طرز پر بنائے گئے کلیسا کے آثار ابھی تک ملتے ہیں جسے اہل نجران ’’کعبۂ نجران‘‘ کہتے تھے۔ عرب مشرکین 40 سال اس کی زیارت کو آتے رہے۔ کعبۂ نجران جاہلیت میں شہر نجران سے تقریباً 35 کلومیٹر شمال مشرق میں کوہ تصلال پر بنو عبد المدان حارثی نے تعمیر کیا تھا۔ یہ ابرہہ اشرم کے صنعاء میں بنائے گئے کعبۂ یمن سے الگ تھا۔\n[تصویر: اہل نجران کے کلیسا کے آثار]","",{"v":100354,"fn":"(1) السيرة لابن هشام: 31-34/1","im":["v1_p354.jpg"]}],[334,"§یمن میں فروغ عیسائیت\nیمنی حکمرانوں میں سے صرف شبع عبد کمیل نے عیسائیت قبول کی تھی۔ باقی تابعہ اکثر یہودی اور کم تر ستارہ پرست تھے۔(1)\nجب حبشیوں نے 525ء میں دوبارہ یمن پر قبضہ کیا اور ابرہہ اشرم نے حکومت یمن کی باگ ڈور اپنے ہاتھ میں لی تو اس نے بڑے جوش و خروش کے ساتھ عیسائیت کو فروغ دینے کی کوشش کی، اس نے صنعاء میں ایک کلیسا تعمیر کیا اور کوشش کی کہ اہل عرب کو مکہ مکرمہ میں واقع بیت اللہ سے روک کر کلیسائے یمن کا حج کرائے اور بیت اللہ کو ڈھا دے۔ لیکن اس کی اس جرات پر اللہ تعالیٰ نے اسے ایسی سزا دی کہ وہ قیامت تک کے لیے عبرت بن گیا۔(2)\nدوسری طرف رومی علاقوں کی ہمسائیگی کے سبب آل غسان، بنو تغلب اور بنو طے وغیرہ قبائل عرب میں بھی عیسائیت پھیل گئی تھی بلکہ حیرہ کے بعض عرب بادشاہوں نے بھی عیسائی مذہب قبول کر لیا تھا۔(3)\n[تصویر: صنعاء میں ابرہہ کے تعمیر شدہ کلیسا کے آثار]","",{"v":100355,"fn":"(1) تاريخ ارض القرآن (كامل): 234/1\n(2) دیکھیے: متداول کتب تفاسیر میں سورۂ فیل کی تفسیر اور کتاب ہذا کا باب \"عام الفیل\"\n(3) الرحيق المختوم، ص: 53","im":["v1_p355.jpg"]}],[335,"4\n§عرب میں مجوسیت اور صابئیت\n§مجوسیت\nمجوسی مذہب کو زیادہ تر اہل فارس کے ہمسایہ عربوں میں فروغ حاصل ہوا تھا، مثلاً: عراق عرب، بحرین (الاحساء)، ہجر اور خلیج عربی کے ساحلی علاقے۔ ان کے علاوہ یمن پر فارسی قبضے کے دوران میں وہاں بھی اکا دکا افراد نے مجوسیت قبول کی۔(1)\n[تصویر: وسطی ایران میں مجوسی آتش کدہ]\n§صابئیت\nصابئین ستارہ پرست قوم تھی۔ عراق وغیرہ کے آثار قدیمہ کی کھدائی کے دوران میں جو کتبات برآمد ہوئے ہیں ان سے پتا چلتا ہے کہ حضرت ابراہیم علیہ السلام کی کلدانی قوم کا مذہب صابئیت تھا۔ دور قدیم میں شام و یمن کے بہت","",{"v":100356,"fn":"(1) الرحيق المختوم، ص: 54","im":["v1_p356.jpg"]}],[336,"سے باشندے بھی اسی مذہب کے پیرو تھے۔ لیکن جب یہودیت اور پھر عیسائیت کا دور دورہ ہوا تو صابی مذہب مٹتا چلا گیا، تاہم مجوس کے ساتھ خلط ملط ہو کر یا ان کے پڑوس میں عراق عرب اور خلیج عربی کے ساحل پر اس مذہب کے کچھ نہ کچھ پیروکار باقی رہے۔(1)\nمجوسیت اور صابئیت اور ان کے عقائد کی مزید تفصیل ’’عرب کی ہمسایہ اقوام، سلطنتیں اور مذاہب‘‘ میں ملاحظہ کیجیے۔\n[تصویر: بصرہ (عراق) میں صابئین کا عبادت خانہ]","",{"v":100357,"fn":"(1) تاريخ ارض القرآن (كامل): 193-208/2، الرحيق المختوم، ص: 54","im":["v1_p357.jpg"]}],[337,"§عرب کی مشرکانہ رسوم و توہمات\nجاہلیت کے عقائد و اعمال کے باوجود قریش میں دین ابراہیمی کی کچھ باقیات بھی موجود تھیں، انھوں نے یہ دین پورے طور پر نہیں چھوڑا تھا۔ وہ بیت اللہ کی تعظیم اور اس کا طواف کرتے، حج و عمرہ ادا کرتے اور ہدی کے جانوروں کی قربانی کرتے تھے، البتہ انھوں نے دین ابراہیمی میں بہت سی بدعتیں ایجاد کر کے شامل کر دی تھیں، مثلاً:\n§حُمس کا خصوصی مقام\nقریش کی ایک بدعت یہ تھی کہ وہ کہتے تھے: ہم حضرت ابراہیم علیہ السلام کی اولاد، حرم کے پاسبان، بیت اللہ کے والی اور مکہ کے باشندے ہیں۔ کوئی شخص ہمارا ہم مرتبہ نہیں اور نہ کسی کے حقوق ہمارے حقوق کے مساوی ہیں۔ اسی بنا پر وہ اپنا نام حُمس (بہادر اور گرم جوش) رکھتے تھے۔ لہٰذا ہمارے شایان شان نہیں کہ ہم حدود حرم سے باہر جائیں، چنانچہ حج کے دوران میں یہ لوگ عرفات نہیں جاتے تھے اور نہ وہاں سے افاضہ کرتے تھے بلکہ مُزْدَلِفَہ ہی میں ٹھہر کر وہیں سے افاضہ کر لیتے تھے۔(1) اللہ تعالیٰ نے اس بدعت کی اصلاح کرتے ہوئے فرمایا:\n﴿ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ﴾ (البقرة 2:199)\n’’پھر تم لوگ بھی وہیں سے افاضہ کرو (لوٹو) جہاں سے سارے لوگ افاضہ کرتے ہیں۔‘‘(2)\nحُمس میں ان لوگوں کو بھی شامل کیا جاتا تھا جو حل (بیرون حرم) یا حرم کے عرب باسیوں کی اولاد ہوتی۔ ان کے احکام بھی وہی ہوتے جو قریش مکہ کے ہوتے تھے۔ جو چیزیں قریش کے لیے حلال ہوتیں، ان کے لیے بھی حلال ہوتیں اور جو قریش پر حرام ہوتیں، ان کے لیے بھی حرام ہوتیں۔(3)\n§حُمس کے لیے حالت احرام کی بندشیں\nقریش کہتے تھے کہ حُمس کے لیے احرام کی حالت میں پنیر اور گھی بنانا درست نہیں، نیز وہ بال والے گھر (کمبل کے","",{"v":100358,"fn":"(1) عرفہ کے دن سورج غروب ہونے کے بعد میدان عرفات سے مزدلفہ جانا، وہاں مغرب اور عشاء کی نمازیں جمع اور قصر کر کے ادا کرنا، رات مزدلفہ میں بسر کرنا اور صبح فجر کی نماز مزدلفہ ہی میں ادا کرنا، یہ سب اعمال افاضہ کہلاتے ہیں۔ (معجم لغة الفقهاء، ص: 79)\n(2) السيرة لابن هشام: 199/1، صحيح البخاري: 1665، صحيح مسلم: 1219\n(3) السيرة لابن هشام: 199/1"}],[338,"خیمے) میں داخل ہو سکتے ہیں نہ سایہ حاصل کر سکتے ہیں۔ اگر سایہ حاصل کرنا ہو تو چمڑے کے خیمے میں حاصل کریں۔(1)\n§حج یا عمرہ کرنے والے بیرونی زائرین کا کھانا\nوہ کہتے تھے کہ بیرون حرم کے باشندے حج یا عمرہ کرنے آئیں اور وہ اپنے ساتھ حل سے کھانے پینے کی کوئی چیز لے کر آئیں تو اہل حل کے لیے اسے کھانا درست نہیں۔(2)\n§برہنہ طواف کی قبیح رسم\nقریش نے بیرون حرم کے باشندوں کو حکم دے رکھا تھا کہ وہ حرم میں آنے کے بعد پہلا طواف حُمس سے حاصل کیے ہوئے کپڑوں ہی میں کریں، چنانچہ اگر ان کا کپڑا دستیاب نہ ہوتا تو مرد ننگے طواف کرتے اور عورتیں اپنے کپڑے اتار کر صرف ایک چھوٹا سا کھلا ہوا کرتا پہن لیتیں اور اس میں طواف کرتیں اور دوران طواف یہ شعر پڑھتی تھیں:\nاليَوْمَ يَبْدُو بَعْضُهُ أَوْ كُلُّهُ وَمَا بَدَا مِنْهُ فَلَا أُحِلُّهُ\n’’آج جسم کا کچھ حصہ برہنہ ہوگا یا سارا لیکن جو برہنہ ہو، میں دوسروں کے لیے اسے حلال نہیں کروں گی۔‘‘\nاللہ تعالیٰ نے اس خرافات کے خاتمے کے لیے فرمایا:\n﴿يَا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ﴾ (الأعراف 7:31)\n’’اے آدم کے بیٹو! ہر مسجد کے پاس اپنی زینت (ساتر لباس) اختیار کر لیا کرو۔‘‘\nبہر حال اگر کوئی عورت یا مرد برتر اور معزز بن کر بیرون حرم سے لائے ہوئے اپنے ہی کپڑوں میں طواف کر لیتا تو طواف کے بعد ان کپڑوں کو پھینک دیتا، ان سے نہ خود فائدہ اٹھاتا نہ کوئی اور۔(3)\n§حالت احرام میں گھر کے عقب سے آنا\nقریش حالت احرام میں گھر کے اندر دروازے سے داخل نہ ہوتے بلکہ گھر کے پچھواڑے ایک بڑا سا سوراخ بنا لیتے اور اسی سے آتے جاتے اور اپنے اس اجڑ پن کو نیکی سمجھتے۔ قرآن کریم نے اس سے بھی منع فرمایا، فرمان الہی ہے:\n﴿وَلَيْسَ الْبِرُّ بِأَن تَأْتُوا الْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ الْبِرَّ مَنِ اتَّقَىٰ وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾ (البقرة 2:189)","",{"v":100359,"fn":"(1) السيرة لابن هشام: 202/1\n(2) السيرة لابن هشام: 202/1\n(3) السيرة لابن هشام: 202,203/1، صحيح البخاري: 1665"}],[339,"’’اور نیکی یہ نہیں کہ تم اپنے گھروں میں ان کے پچھواڑے کی طرف سے آؤ بلکہ نیکی یہ ہے کہ آدمی پرہیزگاری اختیار کرے اور تم اپنے گھروں میں ان کے دروازوں سے آؤ اور تم اللہ سے ڈرو تا کہ تم فلاح پاؤ۔‘‘(1)\nیہی شرک، بت پرستی اور توہمات و خرافات پر مبنی عقیدہ و عمل والا دین اہل عرب کا تھا۔\n§فال گیری اور جوا\nمشرکین عرب ازلام، یعنی فال کے تیر بھی استعمال کرتے تھے۔ (ازلام، زَلَم کی جمع ہے۔ زَلَم اس تیر کو کہتے ہیں جس کے پر نہ لگے ہوں۔) فال گیری کے لیے استعمال ہونے والے یہ تیر تین قسم کے ہوتے تھے۔ ایک وہ جن پر صرف ’’ہاں‘‘ یا ’’نہیں‘‘ لکھا ہوتا تھا۔ اس قسم کے تیر سفر اور نکاح وغیرہ جیسے کاموں کے لیے استعمال کیے جاتے تھے۔ اگر فال میں ’’ہاں‘‘ نکلتا تو مطلوبہ کام کر لیا جاتا، اگر ’’نہیں‘‘ نکلتا تو سال بھر کے لیے ملتوی کر دیا جاتا اور آئندہ سال پھر فال نکالی جاتی۔\nفال گیری کے تیروں کی دوسری قسم وہ تھی جن پر پانی، یعنی نیا کنواں کھودنے اور دیت وغیرہ کے معاملات درج ہوتے تھے۔ تیسری قسم وہ تھی جن پر یہ درج ہوتا تھا کہ ’’تم میں سے ہے یا تمھارے غیر سے ہے یا ملحق ہے۔‘‘ ان تیروں کا مصرف یہ تھا کہ جب کسی کے نسب میں شبہ ہوتا تو اسے ایک سو درہم اور ایک اونٹ سمیت ہُبل کے پاس لے جاتے۔ اونٹ اور درہم کو تیر والے مہنت کے حوالے کرتے۔ وہ تمام تیروں کو ایک ساتھ ملا کر گھماتا، جھنجھوڑتا، پھر ایک تیر نکالتا۔ اب اگر یہ نکلتا کہ ’’تم میں سے ہے‘‘ تو وہ ان کے قبیلے کا ایک معزز فرد قرار پاتا اور اگر یہ برآمد ہوتا کہ ’’تمھارے غیر سے ہے‘‘ تو حلیف قرار پاتا اور اگر یہ نکلتا کہ ’’ملحق ہے‘‘ تو ان کے اندر اپنی حیثیت پر برقرار رہتا، نہ قبیلے کا فرد مانا جاتا نہ حلیف۔(2)\nاس سے ملتا جلتا ایک رواج مشرکین میں جوا کھیلنے اور جوئے کے تیر استعمال کرنے کا تھا۔ تیر کی نشاندہی پر وہ جوئے کا اونٹ ذبح کر کے اس کا گوشت بانٹتے تھے۔ اس کا طریقہ یہ تھا کہ جوا کھیلنے والے ایک اونٹ ذبح کر کے اسے دس یا اٹھائیس حصوں میں تقسیم کرتے، پھر تیروں سے قرعہ اندازی کرتے۔ کسی تیر پر جیت کا نشان بنا ہوتا اور کوئی تیر بے نشان ہوتا۔ جس کے نام پر جیت کے نشان والا تیر نکلتا، وہ تو کامیاب مانا جاتا اور اپنا حصہ لیتا اور جس کے نام پر بے نشان تیر نکلتا، اسے قیمت دینی پڑتی۔","",{"v":100360,"fn":"(1) الرحيق المختوم، ص: 51,52\n(2) السيرة لابن إسحاق: 85,86/1، السيرة لابن هشام: 152,153/1، فتح الباري: 351/8"}],[340,"§کاہنوں، عرافوں اور نجومیوں کی خبروں پر ایمان\nمشرکین عرب کاہنوں، عرافوں اور نجومیوں کی خبروں پر بھی ایمان رکھتے تھے۔ کاہن اسے کہتے ہیں جو آنے والے واقعات کی پیش گوئی کرے اور راز ہائے سربستہ سے واقفیت کا دعویدار ہو۔ بعض کاہنوں کا یہ بھی دعویٰ تھا کہ ایک جن ان کے تابع ہے جو انھیں خبریں پہنچاتا رہتا ہے۔ بعض کاہن کہتے تھے کہ انھیں ایسا فہم عطا کیا گیا ہے جس کے ذریعے سے وہ غیب کا پتا لگا لیتے ہیں۔ عراف اس بات کے مدعی تھے کہ جو آدمی ان سے کوئی بات پوچھنے آتا ہے، اس کے قول و فعل سے یا اس کی حالت سے، کچھ مقدمات اور اسباب کے ذریعے سے وہ جائے واردات کا پتا لگا لیتے ہیں۔ نجومی اسے کہتے ہیں جو ستاروں پر غور کر کے اور ان کی رفتار و اوقات کا حساب لگا کر پتا لگاتا ہے کہ دنیا میں آئندہ کیا حالات و واقعات پیش آئیں گے۔(1)\nاسی طرح ان نجومیوں کی خبروں کو ماننا در حقیقت ستاروں پر ایمان لانا ہے اور ستاروں پر ایمان لانے کی ایک صورت یہ بھی تھی کہ مشرکین عرب نچھتروں پر ایمان رکھتے تھے اور کہتے تھے کہ ہم پر فلاں اور فلاں نچھتر (ستارے کی برکت سے بارش ہوئی ہے۔(2)\nاسلام نے ان کاہنوں اور عرافوں کے پاس جانے سے سختی سے منع کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿مَنْ أَتَىٰ عَرَّافًا فَسَأَلَهُ عَنْ شَيْءٍ لَمْ تُقْبَلْ لَهُ صَلَاةٌ أَرْبَعِينَ لَيْلَةً﴾\n’’جو شخص کسی نجومی کے پاس جائے اور اس سے کسی چیز کے بارے میں دریافت کرے تو اس کی چالیس دن تک نماز قبول نہیں ہوتی۔‘‘(3)\nاسی طرح مسند احمد میں نبی کریم صلی اللہ علیہ وسلم کا ارشاد ہے:\n﴿مَنْ أَتَىٰ كَاهِنًا أَوْ عَرَّافًا فَصَدَّقَهُ بِمَا يَقُولُ، فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَىٰ مُحَمَّدٍ﴾\n’’جو شخص کسی نجومی یا قیافہ شناس کے پاس آئے اور اس کی بات کی تصدیق کرے تو اس نے گویا محمد صلی اللہ علیہ وسلم پر اتاری گئی شریعت کا انکار کیا۔‘‘(4)\nسیدنا عمران بن حصین رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿لَيْسَ مِنَّا مَنْ تَطَيَّرَ أَوْ تُطُيِّرَ لَهُ، أَوْ تَكَهَّنَ أَوْ تُكُهِّنَ لَهُ أَوْ سَحَرَ أَوْ سُحِرَ لَهُ، وَمَنْ أَتَىٰ كَاهِنًا﴾","",{"v":100361,"fn":"(1) مرعاة المفاتيح: 248/2\n(2) شرح النووي على صحيح مسلم: 79,80/2\n(3) صحيح مسلم: 2230\n(4) مسند أحمد: 429/2"}],[341,"﴿فَصَدَّقَهُ بِمَا يَقُولُ فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَىٰ مُحَمَّدٍ﴾\n’’وہ شخص جو برا شگون لے یا اس کے لیے برا شگون لیا جائے، کہانت کرے یا اس کے لیے کہانت کی جائے، جادو کرے یا اس کے لیے جادو کیا جائے، وہ ہم میں سے نہیں اور جو شخص کسی کاہن کے پاس آئے اور اس کی بات کی تصدیق کرے تو اس نے گویا محمد صلی اللہ علیہ وسلم پر نازل شدہ شریعت کا انکار کیا۔‘‘(1)\n§بدشگونی کا عقیدہ\nمشرکین میں بدشگونی کا بھی رواج تھا۔ اسے عربی میں طیرہ کہتے ہیں۔ اس کی صورت یہ تھی کہ مشرکین کسی چڑیا یا ہرن کے پاس جا کر اسے بھگاتے تھے۔ اگر وہ داہنی جانب بھاگتا تو اسے اچھائی اور کامیابی کی علامت سمجھ کر اپنا کام کر گزرتے اور اگر بائیں جانب بھاگتا تو اسے نحوست کی علامت سمجھ کر اپنے کام سے باز رہتے۔ اسی طرح اگر کوئی چڑیا یا جانور راستہ کاٹ دیتا تو اسے بھی منحوس سمجھتے۔\nاسی سے ملتی جلتی ایک حرکت یہ بھی تھی کہ مشرکین خرگوش کے ٹخنے کی ہڈی لٹکاتے تھے اور بعض دنوں، مہینوں، جانوروں، گھروں اور عورتوں کو منحوس سمجھتے تھے۔ بیماریوں کی چھوت کے قائل تھے اور روح کے الو بن جانے کا عقیدہ رکھتے تھے۔ ان کا عقیدہ تھا کہ جب تک مقتول کا بدلہ نہ لیا جائے، اسے سکون نہیں ملتا اور اس کی روح الو بن کر بیابانوں میں گردش کرتی رہتی ہے اور ’’پیاس، پیاس‘‘ یا ’’مجھے پلاؤ، مجھے پلاؤ‘‘ کی صدا لگاتی رہتی ہے۔ جب اس کا بدلہ لے لیا جاتا ہے تو اسے راحت اور سکون مل جاتا ہے۔(2) نبی اکرم محمد صلی اللہ علیہ وسلم کے لائے ہوئے اسلام نے ان تمام مشرکانہ عقائد اور خرافات کی جڑ کاٹ دی اور اللہ تعالیٰ کا خالص دین دنیا میں جاری و ساری ہو گیا۔","",{"v":100362,"fn":"(1) صحيح الترغيب والترهيب للألباني: 3041\n(2) فتح الباري: 323/7 و 297/10، الرحيق المختوم، ص: 51"}],[342,"باب 5\n§جزیرہ نمائے عرب کی معاشرت، تجارت اور ثقافت\nزمانہ جاہلیت میں شادی بیاہ، اختلاط مرد و زن کی متعدد صورتوں، قبائلی تعصبات، تجارتی میلوں اور عربی شعر و ادب کے مختلف لہجوں اور ارتقائی مدارج کا جائزہ","",{"v":100363,"im":["v1_p363.jpg"]}],[343,"﴿وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ﴾\n’’اور یقیناً آپ خلق عظیم پر (کاربند) ہیں۔‘‘ (القلم 68:4)","",{"v":100364}],[344,"§اس باب میں\nعرب کے معاشرتی حالات، جاہلیت میں نکاح اور اختلاط مرد و زن کی مختلف صورتوں کا تذکرہ ہے، نیز قبائلی عصبیت، جاہلیت کے تجارتی میلوں، عربوں کے بعض اعلیٰ اخلاق اور عربی زبان و ادب کا احاطہ کیا گیا ہے۔ اُم الالسنہ عربی کی مختلف ذیلی شاخوں کا جائزہ لیتے ہوئے شمالی و جنوبی عربی کے فرق، عربی زبان کے مختلف ادوار، اس کی ترقی کے اسباب اور عربوں کی فطری خطابت، مختلف لب و لہجہ، خطیب عرب قس بن ساعدہ، عرب شعراء کے طبقات کا تعارف اور کندہ کے شہزادے امرؤ القیس کے منتخب اشعار پیش کر کے قارئین کرام کی خدمت میں مرقع معلومات تیار کیا گیا ہے۔","",{"v":100365,"im":["v1_p365.jpg"]}],[345,"1\n§جزیرہ نمائے عرب کی معاشرت\nعرب کے طبقہ اشراف میں مرد و عورت کا تعلق خاصا ترقی یافتہ تھا۔ عورت کو بڑی خود مختاری حاصل تھی۔ اس کی بات مانی جاتی تھی اور اس کا اتنا احترام اور تحفظ کیا جاتا تھا کہ اس کی خاطر تلواریں نکل پڑتی تھیں۔ اس کے باوجود بلا نزاع مرد ہی خاندان کا سربراہ مانا جاتا تھا اور اس کی بات فیصلہ کن ہوا کرتی تھی۔ اس طبقے میں مرد اور عورت کا تعلق عقد نکاح کے ذریعے سے ہوتا تھا اور یہ نکاح عورت کے ولی کی زیر نگرانی انجام پاتا تھا۔\n§جاہلیت میں نکاح کی 4 صورتیں\nدوسرے طبقوں میں مرد و عورت کے اختلاط کی اور بھی کئی صورتیں تھیں جنھیں بدکاری و زنا کاری کے سوا کوئی اور نام نہیں دیا جاسکتا۔ سیدہ عائشہ رضی اللہ عنہا کا بیان ہے کہ جاہلیت میں نکاح کی چار صورتیں تھیں۔ ایک تو وہی صورت تھی جو آج بھی لوگوں میں رائج ہے کہ ایک آدمی دوسرے آدمی کو اس کی زیر ولایت لڑکی کے لیے نکاح کا پیغام دیتا، پھر منظوری کے بعد مہر دے کر اس سے نکاح کر لیتا۔\nدوسری صورت یہ تھی کہ عورت جب حیض سے پاک ہوتی تو اس کا شوہر کہتا کہ فلاں شخص کو بلا کر اس سے صحبت کرو۔ شوہر خود اس سے الگ تھلگ رہتا اور اس کے قریب نہ جاتا یہاں تک کہ واضح ہو جاتا کہ جس آدمی سے صحبت کی تھی، اس سے حمل ٹھہر گیا ہے۔ جب حمل واضح ہو جاتا تو اس کے بعد اگر شوہر چاہتا تو اس عورت کے پاس جاتا۔ ایسا اس لیے کیا جاتا تھا کہ لڑکا شریف اور باکمال پیدا ہو۔ اس نکاح کو نکاح استبضاع کہا جاتا تھا (اور اسی کو ہندومت میں نیوگ کہتے تھے۔)(1)\nنکاح کی تیسری صورت یہ تھی کہ دس آدمیوں سے کم کی ایک جماعت اکٹھی ہوتی۔ سب کے سب ایک ہی عورت کے پاس جاتے اور بدکاری کرتے۔ جب وہ عورت حاملہ ہو جاتی اور بچہ پیدا ہوتا تو پیدائش کے چند دن بعد وہ عورت سب کو بلا بھیجتی اور سب کو آنا پڑتا۔ کسی کی مجال نہ تھی کہ کوئی نہ آئے۔ اس کے بعد وہ عورت کہتی کہ آپ لوگوں کا جو","",{"v":100366,"fn":"(1) منو دھرم شاستر، ص: 212"}],[346,"معاملہ تھا، وہ تو آپ جانتے ہی ہیں اور اب میرے بطن سے بچہ پیدا ہوا ہے اور اے فلاں! وہ تیرا بیٹا ہے۔ وہ عورت ان میں سے جس کا نام چاہتی، لیتی اور وہ اُس کا لڑکا مان لیا جاتا۔\nچوتھا نکاح یہ تھا کہ بہت سے لوگ اکٹھے ہوتے اور کسی عورت کے پاس جاتے۔ وہ اپنے پاس کسی آنے والے کو انکار نہ کرتی۔ یہ رنڈیاں ہوتی تھیں جو اپنے دروازوں پر جھنڈیاں گاڑے رکھتی تھیں تا کہ نشانی کا کام دیں اور جو ان کے پاس جانا چاہے، بے دھڑک چلا جائے۔ جب ایسی عورت حاملہ ہوتی اور بچہ پیدا ہوتا تو سب کے سب اس کے پاس جمع ہوتے اور قیافہ شناس کو بلاتے۔ قیافہ شناس اپنی رائے کے مطابق اس لڑکے کو کسی بھی شخص کے ساتھ ملحق کر دیتا، پھر یہ اسی سے منسوب ہو جاتا اور اس کا لڑکا کہلاتا، وہ اس سے انکار نہ کر سکتا تھا۔ جب اللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم کو مبعوث فرمایا تو جاہلیت کے سارے نکاح فسخ کر دیے۔ صرف ایک نکاح باقی رہا جو آج بھی رائج ہے۔\n§مرد و زن کے میل ملاپ کی دیگر صورتیں\nعرب میں مرد و عورت کے ارتباط کی بعض صورتیں ایسی بھی تھیں جو تلوار کی دھار اور نیزے کی نوک پر وجود میں آتی تھیں، یعنی قبائلی جنگوں میں غالب آنے والا قبیلہ مغلوب قبیلے کی عورتوں کو قید کر کے اپنے حرم میں داخل کر لیتا تھا لیکن ایسی عورت سے پیدا ہونے والی اولاد زندگی بھر عار محسوس کرتی تھی۔\nزمانہ جاہلیت میں کسی تحدید کے بغیر متعدد بیویاں رکھنا بھی ایک معروف بات تھی۔(2) لوگ ایسی دو عورتیں بھی بیک وقت نکاح میں رکھ لیتے تھے جو آپس میں سگی بہنیں ہوتی تھیں۔ باپ کے طلاق دینے یا وفات پانے کے بعد بیٹا اپنی سوتیلی ماں سے بھی نکاح کر لیتا تھا۔(3) طلاق کا اختیار بھی مرد کو حاصل تھا اور اس کی کوئی حد متعین نہ تھی۔(4) زنا کاری تمام طبقات میں عروج پر تھی۔ کوئی طبقہ یا انسانوں کی کوئی قسم اس سے مستثنیٰ نہ تھی، البتہ کچھ مرد اور کچھ عورتیں ایسی ضرور تھیں جنھیں اپنی بڑائی کا احساس زنا سے باز رکھتا تھا۔ اس سلسلے میں آزاد عورتوں کا حال لونڈیوں کے مقابل نسبتاً اچھا تھا۔ اہل جاہلیت کی غالب اکثریت اس برائی کی طرف منسوب ہونے میں کوئی عار محسوس نہیں کرتی تھی، چنانچہ سنن ابو داود میں مروی ہے کہ ایک دفعہ ایک آدمی نے کھڑے ہو کر کہا: ’’اے اللہ کے رسول! فلاں شخص میرا بیٹا ہے۔ میں نے جاہلیت میں اس کی ماں سے زنا کیا تھا۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اسلام میں ایسے دعوے کی گنجائش نہیں۔ جاہلیت کی بات گئی، اب تو لڑکا اس کا ہوگا جس کی بیوی یا لونڈی سے پیدا ہوا اور زنا کار کے لیے پتھر ہیں۔‘‘(5)","",{"v":100367,"fn":"(1) صحیح البخاری: 5127\n(2) سنن أبی داود: 2241,2242\n(3) السنن الکبریٰ للبیہقی: 163/7\n(4) سنن أبی داود: 2195\n(5) سنن أبی داود: 2274"}],[347,"فتح مکہ کے موقع پر سیدنا سعد بن ابی وقاص رضی اللہ عنہ اور عبد بن زمعہ رضی اللہ عنہ کے درمیان زمعہ کی لونڈی کے بیٹے کے بارے میں جھگڑا ہوا تو وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ سیدنا سعد رضی اللہ عنہ نے کہا: ’’یہ میرا بھتیجا ہے، میرے بھائی نے مجھ سے اس کے متعلق عہد لیا تھا۔‘‘ عبد بن زمعہ رضی اللہ عنہ نے کہا: ’’یہ میرا بھائی ہے، میرے باپ کی لونڈی کا بیٹا ہے اور اس کے بستر پر پیدا ہوا ہے۔‘‘ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’اے عبد بن زمعہ! وہ تیرا بھائی ہے…… بچہ اسی کا ہوتا ہے جس کے بستر پر پیدا ہو، البتہ زانی کے لیے پتھر ہیں۔‘‘(1)\n§لڑکوں پر فخر اور لڑکیوں کو زندہ درگور کرنا\nجاہلیت میں باپ اور اولاد کا تعلق بھی مختلف نوعیت کا تھا۔ کچھ تو ایسے تھے جو کہتے تھے:\nإِنَّمَا أَوْلَادُنَا بَيْنَنَا أَكْبَادُنَا تَمْشِي عَلَى الْأَرْضِ\n’’ہمارے درمیان ہماری اولاد ہمارے کلیجے ہیں جو روئے زمین پر چلتے پھرتے ہیں۔‘‘\nلیکن دوسری طرف کچھ ایسے بھی تھے جو لڑکیوں کی پیدائش کو اپنے لیے باعث رسوائی خیال کرتے ہوئے انھیں زندہ دفن کر دیتے تھے۔(2) بعض لوگ اپنے بچوں کو فقر و فاقہ کے ڈر سے مار ڈالتے تھے۔(3) لیکن یہ کہنا مشکل ہے کہ یہ سنگ دلی بڑے پیمانے پر رائج تھی کیونکہ عرب اپنے دشمن سے اپنی حفاظت کے لیے دوسروں کی بہ نسبت کہیں زیادہ اولاد کے محتاج تھے اور اس کا احساس بھی رکھتے تھے۔(4)\n§قبائلی عصبیت اور جنگیں\nعربوں کی قبائلی عصبیت اور قرابت کا تعلق ہی ان کے سماجی نظام کی بنیاد تھا۔ وہ لوگ اس مشہور مثل پر عمل پیرا تھے کہ انْصُرْ أَخَاكَ ظَالِمًا أَوْ مَظْلُومًا ’’اپنے بھائی کی مدد کرو، خواہ وہ ظالم ہو یا مظلوم۔‘‘(5) اس مثل کے معنی میں ابھی وہ اصلاح نہیں ہوئی تھی جو بعد میں اسلام کے ذریعے سے کی گئی، یعنی ظالم کی مدد یہ ہے کہ اُسے ظلم سے باز رکھا جائے، البتہ شرف و سرداری میں ایک دوسرے سے آگے نکل جانے کا جذبہ اکثر قبائل کے درمیان جنگ کا سبب بن جایا کرتا تھا جیسا کہ اوس و خزرج، عبس و ذبیان اور بکر و تغلب وغیرہ کے واقعات میں دیکھا جا سکتا ہے۔","",{"v":100368,"fn":"(1) صحیح البخاری: 2053\n(2) النحل 16:58,59\n(3) بنی إسرآءیل 17:31\n(4) الرحیق المختوم، ص: 57\n(5) یہ صرف عربی ضرب المثل نہیں بلکہ رسول اللہ صلی اللہ علیہ وسلم کی زبان اطہر سے ادا ہونے والی ایک حدیث بن چکی ہے، دیکھیے: صحیح البخاری: 2443، 2444"}],[348,"دین اور خرافات کے آمیزے سے تیار شدہ بعض رسوم و عادات کی بدولت بسا اوقات جنگ کی حدت و شدت میں کمی آجاتی تھی اور بعض حالات میں موالات، حلف اور تابعداری کے اصولوں پر مختلف قبائل یکجا ہو جاتے تھے۔ علاوہ ازیں حرمت والے مہینوں میں لڑائی رک جاتی تھی جو کہ حصول معاش کے لیے سراپا رحمت ثابت ہوتے تھے۔(1)","",{"v":100369,"fn":"(1) صحیح البخاری: 4376، فتح الباری: 114/8، نیز دیکھیے: الرحیق المختوم، ص: 57"}]])